    chaptersCompleted: { ch1: false, ch2: false, ch3: false, ch4: false, ch5: false, ch6: false, ch7: false, ch8: false, ch9: false, ch10: false },
    chapterScores: { ch1: 0, ch2: 0, ch3: 0, ch4: 0, ch5: 0, ch6: 0, ch7: 0, ch8: 0, ch9: 0, ch10: 0 },
    dimensionScores: { clarity:0, precision:0, accuracy:0, relevance:0, consistency:0, logicalCorrectness:0, completeness:0, fairness:0 },
    dimensionAttempts: { clarity:0, precision:0, accuracy:0, relevance:0, consistency:0, logicalCorrectness:0, completeness:0, fairness:0 },
    questionHistory: [],
    practiceSessions: 0, streak: 0, lastActivity: null,
