      ch1: { status: 'locked', currentStep: 1, knowledgeMap: {nodes:[], links:[]}, reportDrafts: [], finalReport: '', finalKnowledgeMap: null, hintsUsed: {}, iterations: 0, aiScore: null, aiFeedback: '', reflection: {q1:'',q2:'',q3:''}, submittedAt: null },
