function deleteStudentV7(studentId) {
  if (!confirm("Delete student '" + studentId + "'? This will remove all their data.")) return;
  v7AdminDeleteStudent(studentId);
  renderStudentListV7(document.getElementById("contentArea"));
}

function resetStudentPassword(studentId) {
  var newPwd = prompt("Enter new password for " + studentId + ":", "123456");
  if (newPwd === null) return;
  if (newPwd.length < 4) { alert("Password must be at least 4 characters"); return; }
  
  var students = v7AdminGetStudents();
  if (students[studentId]) {
    students[studentId].password = newPwd;
    v7AdminSaveStudents(students);
    alert("Password reset successfully.");
  } else {
    alert("Student not found in registered accounts. This may be a mock student.");
  }
}

// ----- Enhanced Student Detail -----
function viewStudentV7(studentId) {
  var allStudents = v7AdminGetAllStudentsForDisplay();
  var s = allStudents.find(function(stu) { return stu.id === studentId; });
  if (!s) return;
  
  AdminState.selectedStudent = s;
  showStudentModalV7(s);
}

function showStudentModalV7(s) {
  var recs = generateStudentRecommendations(s);
  var initials = s.name.split(' ').map(function(n){return n[0];}).join('').substring(0,2);
  
  var dimScores = s.dimensionScores || {};
  var radarSvg = generateRadarSVG(
    DIMENSIONS.map(function(d){return dimScores[d] || 0;}),
    DIMENSIONS.map(function(d){return DIMENSION_NAMES[d];}),
    300
  );

  var html = "";
  html += '<div class="student-detail-header">';
  html += '<div class="student-detail-avatar">' + initials + '</div>';
  html += '<div style="flex:1;"><div class="student-detail-name">' + s.name + '</div>';
  html += '<div class="student-detail-email">' + s.id + ' &middot; <span class="badge badge-info">' + s.classId + '</span></div></div>';
  html += '<div style="display:flex; gap:6px;">';
  html += '<button class="btn btn-outline btn-sm" data-edit-student="' + s.id + '" onclick="editStudentInfo(this.dataset.editStudent)">Edit</button>';
  html += '<button class="btn btn-outline btn-sm" onclick="closeStudentModal()">Close</button>';
  html += '</div>';
  html += '</div>';

  html += '<div class="grid-2">';
  
  html += '<div>';
  html += '<div style="margin-bottom:16px;"><h4 style="font-size:14px;margin-bottom:12px;">Performance Summary</h4>';
  html += '<div class="grid-2" style="gap:10px;">';
  html += '<div style="background:#f8fafc;padding:12px;border-radius:6px;text-align:center;">';
  html += '<div class="text-sm text-muted">Pretest</div>';
  html += '<div style="font-size:22px;font-weight:700;">' + (s.pretestTaken ? s.pretestScore + '%' : 'N/A') + '</div></div>';
  html += '<div style="background:#f8fafc;padding:12px;border-radius:6px;text-align:center;">';
  html += '<div class="text-sm text-muted">Post-test</div>';
  html += '<div style="font-size:22px;font-weight:700;">' + (s.posttestTaken ? s.posttestScore + '%' : 'N/A') + '</div></div>';
  html += '</div></div>';

  html += '<div style="margin-bottom:16px;"><h4 style="font-size:14px;margin-bottom:12px;">Skill Radar</h4>';
  html += '<div class="radar-container">' + radarSvg + '</div></div>';

  html += '<div><h4 style="font-size:14px;margin-bottom:12px;">Dimension Breakdown</h4>';
  var ranked = DIMENSIONS.map(function(d){return {name:DIMENSION_NAMES[d], score: dimScores[d] || 0};})
    .sort(function(a,b){return b.score - a.score;});
  ranked.forEach(function(item) {
    var pct = Math.round(item.score / 10 * 100);
    html += '<div class="progress-item">';
    html += '<div class="progress-label">' + item.name + '</div>';
    html += '<div class="progress-track"><div class="progress-bar-fill" style="width:' + pct + '%;"></div></div>';
    html += '<div class="progress-value">' + item.score.toFixed(1) + '/10</div>';
    html += '</div>';
  });
  html += '</div>';
  html += '</div>';

  html += '<div>';
  html += '<div style="margin-bottom:16px;"><h4 style="font-size:14px;margin-bottom:12px;">AI Recommendations</h4>';
  recs.forEach(function(rec) {
    html += '<div class="recommendation-card">';
    html += '<h4>&#128161; ' + rec.title + '</h4>';
    html += '<p>' + rec.text + '</p>';
    html += '</div>';
  });
  html += '</div>';

  html += '<div><h4 style="font-size:14px;margin-bottom:12px;">Learning Activity</h4>';
  html += '<div style="background:#f8fafc;padding:12px;border-radius:6px;">';
  html += '<div class="flex-between mb-8"><span class="text-sm text-secondary">Questions Answered</span><span class="text-sm font-600">' + s.questionCount + '</span></div>';
  var ch1Done = s.chaptersCompleted && s.chaptersCompleted.ch1;
  var ch2Done = s.chaptersCompleted && s.chaptersCompleted.ch2;
  html += '<div class="flex-between mb-8"><span class="text-sm text-secondary">Chapter 1</span><span class="text-sm font-600">' + (ch1Done ? 'Complete (' + (s.chapterScores && s.chapterScores.ch1 || 0) + '%)' : 'In Progress') + '</span></div>';
  html += '<div class="flex-between mb-8"><span class="text-sm text-secondary">Chapter 2</span><span class="text-sm font-600">' + (ch2Done ? 'Complete (' + (s.chapterScores && s.chapterScores.ch2 || 0) + '%)' : 'In Progress') + '</span></div>';
  html += '<div class="flex-between"><span class="text-sm text-secondary">Last Active</span><span class="text-sm font-600">' + s.lastActivity + '</span></div>';
  html += '</div></div>';
  
  html += '<div style="margin-top:20px;"><h4 style="font-size:14px;margin-bottom:12px;">PBL Portfolio</h4>';
  if (s.pblProjects) {
    var ch1Status = s.pblProjects.ch1 ? s.pblProjects.ch1.status : 'locked';
    var ch2Status = s.pblProjects.ch2 ? s.pblProjects.ch2.status : 'locked';
    html += '<div class="grid-2" style="gap:10px;">';
    html += '<div style="background:#f8fafc;padding:12px;border-radius:6px;">';
    html += '<div style="font-size:12px;font-weight:600;margin-bottom:4px;">Project 1: Business</div>';
    html += '<div style="font-size:11px;color:var(--text-muted);margin-bottom:6px;">Status: <span class="badge ' + (ch1Status==='completed'?'badge-success':ch1Status==='in_progress'?'badge-info':'badge-muted') + '">' + ch1Status.replace('_',' ') + '</span></div>';
    if (s.pblProjects.ch1 && s.pblProjects.ch1.aiScore !== null && s.pblProjects.ch1.aiScore !== undefined) {
      html += '<div style="font-size:18px;font-weight:700;color:var(--accent);">' + s.pblProjects.ch1.aiScore.toFixed(1) + '/10</div>';
    }
    html += '<button class="btn btn-outline btn-sm mt-8" style="font-size:11px;padding:3px 10px;" data-pbl-student="' + s.id + '" data-pbl-ch="ch1" onclick="viewStudentPBLLarge(this.dataset.pblStudent, this.dataset.pblCh)">View Work</button>';
    html += '</div>';
    html += '<div style="background:#f8fafc;padding:12px;border-radius:6px;">';
    html += '<div style="font-size:12px;font-weight:600;margin-bottom:4px;">Project 2: Marketing</div>';
    html += '<div style="font-size:11px;color:var(--text-muted);margin-bottom:6px;">Status: <span class="badge ' + (ch2Status==='completed'?'badge-success':ch2Status==='in_progress'?'badge-info':'badge-muted') + '">' + ch2Status.replace('_',' ') + '</span></div>';
    if (s.pblProjects.ch2 && s.pblProjects.ch2.aiScore !== null && s.pblProjects.ch2.aiScore !== undefined) {
      html += '<div style="font-size:18px;font-weight:700;color:var(--accent);">' + s.pblProjects.ch2.aiScore.toFixed(1) + '/10</div>';
    }
    html += '<button class="btn btn-outline btn-sm mt-8" style="font-size:11px;padding:3px 10px;" data-pbl-student2="' + s.id + '" data-pbl-ch2="ch2" onclick="viewStudentPBLLarge(this.dataset.pblStudent2, this.dataset.pblCh2)">View Work</button>';
    html += '</div>';
    html += '</div>';
  } else {
    html += '<p class="text-sm text-muted">No PBL data available.</p>';
  }
  html += '</div>';
  
  html += '</div>';
  html += '</div>';
  
  var modalHtml = '<div class="modal-overlay show" id="studentDetailModal">' +
    '<div class="modal" style="max-width:900px;">' +
    '<div class="modal-body" style="padding:20px;">' + html + '</div>' +
    '</div></div>';
  
  var existing = document.getElementById("studentDetailModal");
  if (existing) existing.remove();
  
  document.body.insertAdjacentHTML('beforeend', modalHtml);
  document.getElementById("studentDetailModal").addEventListener("click", function(e) {
    if (e.target === this) closeStudentModal();
  });
}


function editStudentInfo(studentId) {
  var students = v7AdminGetStudents();
  var classes = v7AdminGetClasses();
  var stu = students[studentId];
  
  if (!stu) {
    alert("This is a demo/mock student. Edits are not available for mock students.");
    return;
  }
  
  var html = "";
  html += '<div class="modal-overlay show" id="editStudentModal" onclick="if(event.target===this)closeEditStudentModal()">';
  html += '<div class="modal" style="max-width:420px;">';
  html += '<div class="modal-header"><div class="modal-title">Edit Student</div><button class="modal-close" onclick="closeEditStudentModal()">&times;</button></div>';
  html += '<div class="modal-body">';
  html += '<div class="form-group"><label class="form-label">Student ID</label>';
  html += '<input type="text" class="form-input" value="' + studentId + '" disabled></div>';
  html += '<div class="form-group"><label class="form-label">Name</label>';
  html += '<input type="text" class="form-input" id="editStudentName" value="' + stu.name + '"></div>';
  html += '<div class="form-group"><label class="form-label">Class</label>';
  html += '<select class="form-select" id="editStudentClass">';
  for (var i = 0; i < classes.length; i++) {
    html += '<option value="' + classes[i] + '"' + (classes[i] === stu.classId ? ' selected' : '') + '>' + classes[i] + '</option>';
  }
  html += '</select></div>';
  html += '</div>';
  html += '<div class="modal-footer">';
  html += '<button class="btn btn-outline" onclick="closeEditStudentModal()">Cancel</button>';
  html += '<button class="btn btn-primary" id="saveStudentEditBtn" data-save-sid="' + studentId + '" onclick="saveStudentEdit(this.dataset.saveSid)">Save</button>';
  html += '</div>';
  html += '</div></div>';
  
  var existing = document.getElementById("editStudentModal");
  if (existing) existing.remove();
  document.body.insertAdjacentHTML('beforeend', html);
}


function closeStudentModal() {
  var m = document.getElementById("studentDetailModal");
  if (m) m.remove();
  AdminState.selectedStudent = null;
}

function closeEditStudentModal() {
  var m = document.getElementById("editStudentModal");
  if (m) m.remove();
}

function saveStudentEdit(studentId) {
  var students = v7AdminGetStudents();
  var stu = students[studentId];
  if (!stu) { alert("Student not found."); return; }
  
  var newName = document.getElementById("editStudentName").value.trim();
  var newClass = document.getElementById("editStudentClass").value;
  
  if (!newName) { alert("Name cannot be empty."); return; }
  
  stu.name = newName;
  stu.classId = newClass;
  
  // Save to localStorage
  v7AdminSaveStudents(students);
  
  // Close modal
  closeEditStudentModal();
  
  // Refresh student list
  var area = document.getElementById("adminContent");
  if (area && typeof renderStudentListV7 === "function") {
    renderStudentListV7(area);
  }
  // Also refresh student detail modal if open
  if (AdminState.selectedStudent && AdminState.selectedStudent.id === studentId) {
    var allStudents = v7AdminGetAllStudentsForDisplay();
    var updated = allStudents.find(function(st) { return st.id === studentId; });
    if (updated) {
      AdminState.selectedStudent = updated;
      showStudentModalV7(updated);
    }
  }
}

// ----- Enhanced Dashboard -----
function renderAdminDashboardV7(area) {
  var students = v7AdminGetFilteredStudents();
  var total = students.length;
  var active = students.filter(function(s) { return s.questionCount > 0; }).length;
  var completedCh1 = students.filter(function(s) { return s.chaptersCompleted && s.chaptersCompleted.ch1; }).length;
  var completedPost = students.filter(function(s) { return s.posttestTaken; }).length;
  
  var avgPretest = 0, postCount = 0, avgPost = 0;
  var avgImprovement = 0;
  students.forEach(function(s) {
    if (s.pretestTaken) { avgPretest += s.pretestScore; postCount++; }
    if (s.posttestTaken) avgPost += s.posttestScore;
    if (s.pretestTaken && s.posttestTaken) avgImprovement += (s.posttestScore - s.pretestScore);
  });
  avgPretest = postCount > 0 ? Math.round(avgPretest / postCount) : 0;
  var postStudents = students.filter(function(s) { return s.posttestTaken; });
  avgPost = postStudents.length > 0 ? Math.round(avgPost / postStudents.length) : 0;
  avgImprovement = postStudents.length > 0 ? Math.round(avgImprovement / postStudents.length) : 0;

  var className = AdminV7.currentClass === "__all__" ? "All Classes" : AdminV7.currentClass;
  
  var html = "";
  html += '<h1 class="page-title">Instructor Dashboard</h1>';
  html += '<p class="page-subtitle">Overview of ' + className + ' (' + total + ' students)</p>';

  html += '<div class="grid-4 mb-16">';
  html += '<div class="stat-card"><div class="stat-label">Total Students</div><div class="stat-value">' + total + '</div><div class="stat-change up">' + active + ' active</div></div>';
  html += '<div class="stat-card"><div class="stat-label">Avg. Pretest Score</div><div class="stat-value">' + avgPretest + '%</div><div class="stat-change down">baseline</div></div>';
  html += '<div class="stat-card"><div class="stat-label">Avg. Post-test Score</div><div class="stat-value">' + avgPost + '%</div><div class="stat-change up">' + (avgImprovement > 0 ? '+' + avgImprovement + '% improvement' : 'n/a') + '</div></div>';
  html += '<div class="stat-card"><div class="stat-label">Chapter 1 Complete</div><div class="stat-value">' + completedCh1 + '/' + total + '</div><div class="stat-change up">' + (total > 0 ? Math.round(completedCh1/total*100) : 0) + '% completion</div></div>';
  html += '</div>';

  html += '<div class="grid-2">';
  html += '<div class="card"><div class="card-header"><div class="card-title">Recent Activity</div></div><div class="card-body">';
  
  var recent = students.slice().sort(function(a, b) {
    if (a.lastActivity === "—") return 1;
    if (b.lastActivity === "—") return -1;
    return new Date(b.lastActivity) - new Date(a.lastActivity);
  }).slice(0, 5);
  
  recent.forEach(function(s) {
    html += '<div style="display:flex; justify-content:space-between; align-items:center; padding:10px 0; border-bottom:1px solid var(--border);">';
    html += '<div style="display:flex; align-items:center; gap:10px;">';
    html += '<div style="width:36px;height:36px;border-radius:50%;background:linear-gradient(135deg,var(--accent),var(--success));display:flex;align-items:center;justify-content:center;color:#fff;font-weight:600;font-size:13px;">' + s.name.charAt(0) + '</div>';
    html += '<div><div style="font-size:13px;font-weight:500;">' + s.name + '</div>';
    html += '<div style="font-size:11px;color:var(--text-secondary);">' + s.questionCount + ' questions answered</div></div></div>';
    html += '<div style="font-size:11px;color:var(--text-muted);">' + s.lastActivity + '</div>';
    html += '</div>';
  });
  
  html += '</div></div>';

  html += '<div class="card"><div class="card-header"><div class="card-title">Students Needing Attention</div></div><div class="card-body">';
  
  var needsHelp = students.filter(function(s) {
    return (s.pretestTaken && s.pretestScore < 60) || s.questionCount < 20;
  });
  
  if (needsHelp.length === 0) {
    html += '<p class="text-muted text-sm">All students are doing well!</p>';
  } else {
    needsHelp.slice(0, 5).forEach(function(s) {
      var reason = s.questionCount < 20 ? 'Low engagement' : 'Pretest score low';
      html += '<div style="display:flex; justify-content:space-between; align-items:center; padding:10px 0; border-bottom:1px solid var(--border);">';
      html += '<div><div style="font-size:13px;font-weight:500;">' + s.name + '</div>';
      html += '<div style="font-size:11px;color:var(--danger);">' + reason + '</div></div>';
      html += '<button class="btn btn-outline btn-sm" data-view-student="' + s.id + '" onclick="viewStudentV7(this.dataset.viewStudent)">View</button>';
      html += '</div>';
    });
  }
  
  html += '</div></div>';
  html += '</div>';

  // Class radar
  html += '<div class="card"><div class="card-header"><div class="card-title">Class Average - Skill Radar</div></div><div class="card-body">';
  
  var avgDims = {};
  DIMENSIONS.forEach(function(dim) {
    var total2 = 0, count2 = 0;
    students.forEach(function(s) {
      var ds = s.dimensionScores || {};
      if (s.questionCount > 0 && ds[dim] !== undefined) {
        total2 += ds[dim];
        count2++;
      }
    });
    avgDims[dim] = count2 > 0 ? total2 / count2 : 0;
  });
  
  var avgScores = DIMENSIONS.map(function(d) { return avgDims[d]; });
  var radarSvg = generateRadarSVG(avgScores, DIMENSIONS.map(function(d) { return DIMENSION_NAMES[d]; }), 340);
  html += '<div style="text-align:center;">' + radarSvg + '</div>';
  html += '</div></div>';

  area.innerHTML = html;
}


// ----- Enhanced Class Analytics -----
function renderClassAnalyticsV7(area) {
  var students = v7AdminGetFilteredStudents();
  var className = AdminV7.currentClass === "__all__" ? "All Classes" : AdminV7.currentClass;
  
  var html = '';
  html += '<h1 class="page-title">Class Analytics</h1>';
  html += '<p class="page-subtitle">Aggregated performance data for ' + className + ' (' + students.length + ' students)</p>';

  html += '<div class="grid-3 mb-16">';
  var preAvg = 0, postAvg = 0, preCount = 0, postCount = 0;
  students.forEach(function(s) {
    if (s.pretestTaken) { preAvg += s.pretestScore; preCount++; }
    if (s.posttestTaken) { postAvg += s.posttestScore; postCount++; }
  });
  preAvg = preCount > 0 ? Math.round(preAvg / preCount) : 0;
  postAvg = postCount > 0 ? Math.round(postAvg / postCount) : 0;
  var avgImp = postCount > 0 && preCount > 0 ? postAvg - preAvg : 0;
  
  html += '<div class="stat-card"><div class="stat-label">Avg. Pretest Score</div><div class="stat-value">' + preAvg + '%</div></div>';
  html += '<div class="stat-card"><div class="stat-label">Avg. Post-test Score</div><div class="stat-value">' + postAvg + '%</div></div>';
  html += '<div class="stat-card"><div class="stat-label">Avg. Improvement</div><div class="stat-value text-success">+' + avgImp + '%</div></div>';
  html += '</div>';

  html += '<div class="grid-2">';
  html += '<div class="card"><div class="card-header"><div class="card-title">Class Average - 8 Dimensions</div></div>';
  html += '<div class="card-body">';
  
  var classDims = {};
  DIMENSIONS.forEach(function(dim) {
    var total = 0, count = 0;
    students.forEach(function(s) {
      var ds = s.dimensionScores || {};
      if (s.questionCount > 0 && ds[dim] !== undefined) {
        total += ds[dim];
        count++;
      }
    });
    classDims[dim] = count > 0 ? total / count : 0;
  });
  
  var avgRadar = generateRadarSVG(
    DIMENSIONS.map(function(d){return classDims[d];}),
    DIMENSIONS.map(function(d){return DIMENSION_NAMES[d];}),
    320
  );
  html += '<div style="text-align:center;">' + avgRadar + '</div>';
  html += '</div></div>';

  html += '<div class="card"><div class="card-header"><div class="card-title">Dimension Performance Rank</div></div>';
  html += '<div class="card-body">';
  var ranked = DIMENSIONS.map(function(d){
    return {name: DIMENSION_NAMES[d], score: classDims[d]};
  }).sort(function(a,b){return b.score - a.score;});
  
  ranked.forEach(function(item, idx) {
    var pct = Math.round(item.score / 10 * 100);
    html += '<div style="margin-bottom:14px;">';
    html += '<div class="flex-between mb-4"><span class="text-sm font-600">#' + (idx+1) + ' ' + item.name + '</span>';
    html += '<span class="text-sm text-secondary">' + item.score.toFixed(1) + '/10</span></div>';
    html += '<div style="height:8px; background:#e8ecf1; border-radius:4px; overflow:hidden;">';
    html += '<div style="height:100%; width:' + pct + '%; background:linear-gradient(90deg, var(--accent), var(--success)); border-radius:4px;"></div>';
    html += '</div></div>';
  });
  html += '</div></div>';
  html += '</div>';
  
  // Chapter completion per class (if all classes view)
  if (AdminV7.currentClass === "__all__") {
    var classes = v7AdminGetClasses();
    html += '<div class="card mt-16"><div class="card-header"><div class="card-title">Completion by Class</div></div>';
    html += '<div class="card-body">';
    classes.forEach(function(cls) {
      var clsStudents = students.filter(function(s) { return s.classId === cls; });
      var clsCount = clsStudents.length;
      var ch1Done = clsStudents.filter(function(s) { return s.chaptersCompleted && s.chaptersCompleted.ch1; }).length;
      var ch2Done = clsStudents.filter(function(s) { return s.chaptersCompleted && s.chaptersCompleted.ch2; }).length;
      var pct = clsCount > 0 ? Math.round(ch1Done / clsCount * 100) : 0;
      
      html += '<div style="margin-bottom:14px;">';
      html += '<div class="flex-between mb-4"><span class="text-sm font-600">' + cls + '</span>';
      html += '<span class="text-sm text-secondary">' + ch1Done + '/' + clsCount + ' Ch.1, ' + ch2Done + '/' + clsCount + ' Ch.2</span></div>';
      html += '<div style="height:8px; background:#e8ecf1; border-radius:4px; overflow:hidden;">';
      html += '<div style="height:100%; width:' + pct + '%; background:linear-gradient(90deg, var(--accent), var(--success)); border-radius:4px;"></div>';
      html += '</div></div>';
    });
    html += '</div></div>';
  }

  area.innerHTML = html;
}

