function changeTeacherPassword() {
  var pwd = document.getElementById("newTeacherPwd").value;
  if (pwd.length < 4) { alert("Password must be at least 4 characters"); return; }
  v7AdminSetTeacherPassword(pwd);
  document.getElementById("newTeacherPwd").value = "";
  alert("Password changed successfully!");
}

function resetAllStudentData() {
  if (!confirm("Are you sure you want to reset ALL student data? This cannot be undone.")) return;
  var students = v7AdminGetStudents();
  for (var sid in students) {
    if (students.hasOwnProperty(sid)) {
      var key = V7_ADMIN_STORAGE.DATA_PREFIX + sid;
      localStorage.removeItem(key);
      localStorage.removeItem(key + "_messages");
      localStorage.removeItem(key + "_ai_conv");
    }
  }
  localStorage.removeItem("ctp_student");
  localStorage.removeItem("ctp_messages");
  localStorage.removeItem("ctp_ai_conversation");
  alert("All student data has been reset.");
  location.reload();
}

