// ============================================================
// FEISHU BITABLE SYNC (Admin End)
// ============================================================
var ADMIN_FEISHU_STORAGE_KEY = 'ctp_admin_feishu_config';

function loadAdminFeishuConfig() {
  var saved = localStorage.getItem(ADMIN_FEISHU_STORAGE_KEY);
  if (saved) {
    try { return JSON.parse(saved); } catch(e) {}
  }
  return { app_id: '', app_secret: '', base_token: '', table_id: '' };
}

function saveAdminFeishuConfig() {
  var config = {
    app_id: document.getElementById('adminFeishuAppId').value.trim(),
    app_secret: document.getElementById('adminFeishuAppSecret').value.trim(),
    base_token: document.getElementById('adminFeishuBaseToken').value.trim(),
    table_id: document.getElementById('adminFeishuTableId').value.trim()
  };
  localStorage.setItem(ADMIN_FEISHU_STORAGE_KEY, JSON.stringify(config));
  showAdminFeishuStatus('Settings saved successfully!', 'success');
}

function showAdminFeishuStatus(msg, type) {
  var el = document.getElementById('adminFeishuSyncStatus');
  if (!el) return;
  el.className = 'feishu-sync-status ' + (type || 'info');
  el.textContent = msg;
}

function autoFillAdminFeishuConfig() {
  var config = loadAdminFeishuConfig();
  var appIdEl = document.getElementById('adminFeishuAppId');
  if (appIdEl) appIdEl.value = config.app_id || '';
  var appSecretEl = document.getElementById('adminFeishuAppSecret');
  if (appSecretEl) appSecretEl.value = config.app_secret || '';
  var baseTokenEl = document.getElementById('adminFeishuBaseToken');
  if (baseTokenEl) baseTokenEl.value = config.base_token || '';
  var tableIdEl = document.getElementById('adminFeishuTableId');
  if (tableIdEl) tableIdEl.value = config.table_id || '';
}

async function adminGetFeishuTenantToken(config) {
  var url = 'https://open.feishu.cn/open-apis/auth/v3/tenant_access_token/internal';
  var resp = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json; charset=utf-8' },
    body: JSON.stringify({ app_id: config.app_id, app_secret: config.app_secret })
  });
  var data = await resp.json();
  if (data.code !== 0) {
    throw new Error('Failed to get tenant token: ' + (data.msg || data.code));
  }
  return data.tenant_access_token;
}

async function listAllBitableRecords(token, baseToken, tableId) {
  var allRecords = [];
  var pageToken = '';
  var pageSize = 100;

  while (true) {
    var url = 'https://open.feishu.cn/open-apis/bitable/v1/apps/' + baseToken + '/tables/' + tableId + '/records?page_size=' + pageSize;
    if (pageToken) {
      url += '&page_token=' + encodeURIComponent(pageToken);
    }
    var resp = await fetch(url, {
      method: 'GET',
      headers: { 'Authorization': 'Bearer ' + token }
    });
    var data = await resp.json();
    if (data.code !== 0) {
      throw new Error('List records failed: ' + (data.msg || data.code));
    }
    var items = data.data && data.data.items ? data.data.items : [];
    allRecords = allRecords.concat(items);

    var hasMore = data.data && data.data.has_more;
    var nextToken = data.data && data.data.page_token;
    if (!hasMore || !nextToken || nextToken === pageToken) {
      break;
    }
    pageToken = nextToken;
  }

  return allRecords;
}

async function importFromFeishu() {
  var config = loadAdminFeishuConfig();
  if (!config.app_id || !config.app_secret || !config.base_token || !config.table_id) {
    showAdminFeishuStatus('Please fill in all Feishu settings first.', 'error');
    return;
  }

  var btn = document.getElementById('adminFeishuImportBtn');
  if (btn) { btn.disabled = true; btn.textContent = 'Importing...'; }
  showAdminFeishuStatus('Connecting to Feishu Bitable and fetching records...', 'info');

  try {
    var token = await adminGetFeishuTenantToken(config);
    var records = await listAllBitableRecords(token, config.base_token, config.table_id);

    if (!records || records.length === 0) {
      showAdminFeishuStatus('No records found in Bitable table.', 'info');
      return;
    }

    var summary = {
      success: [],
      failed: [],
      created: [],
      updated: [],
      skipped: []
    };

    for (var i = 0; i < records.length; i++) {
      var record = records[i];
      var fields = record.fields || {};

      // Try to get full export data from the "完整数据JSON" field
      var fullDataJson = fields['完整数据JSON'] || '';
      var importData = null;

      if (fullDataJson && typeof fullDataJson === 'string') {
        try {
          importData = JSON.parse(fullDataJson);
        } catch(e) {
          // If parsing fails, build importData from individual fields
          importData = null;
        }
      }

      // If no full data JSON, build from individual fields
      if (!importData) {
        var studentId = fields['学生ID'] || fields['学号'] || '';
        var name = fields['学生姓名'] || '';
        var email = fields['邮箱'] || '';
        var classCode = fields['班级'] || '';
        var pretestScore = fields['预测试分数'] != null ? fields['预测试分数'] : null;
        var posttestScore = fields['后测试分数'] != null ? fields['后测试分数'] : null;

        var chapterScores = {};
        try {
          if (fields['各章节成绩(JSON)'] && typeof fields['各章节成绩(JSON)'] === 'string') {
            chapterScores = JSON.parse(fields['各章节成绩(JSON)']);
          }
        } catch(e) {}

        var pblProjects = {};
        try {
          if (fields['PBL项目(JSON)'] && typeof fields['PBL项目(JSON)'] === 'string') {
            pblProjects = JSON.parse(fields['PBL项目(JSON)']);
          }
        } catch(e) {}

        var dimensionScores = {};
        try {
          if (fields['维度得分(JSON)'] && typeof fields['维度得分(JSON)'] === 'string') {
            dimensionScores = JSON.parse(fields['维度得分(JSON)']);
          }
        } catch(e) {}

        var aiConversations = [];
        try {
          if (fields['AI对话记录(JSON)'] && typeof fields['AI对话记录(JSON)'] === 'string') {
            aiConversations = JSON.parse(fields['AI对话记录(JSON)']);
          }
        } catch(e) {}

        var discussionPosts = [];
        try {
          if (fields['讨论发帖(JSON)'] && typeof fields['讨论发帖(JSON)'] === 'string') {
            discussionPosts = JSON.parse(fields['讨论发帖(JSON)']);
          }
        } catch(e) {}

        var chaptersCompleted = {};
        var chCount = fields['完成章节数'] || 0;
        for (var ci = 1; ci <= 10; ci++) {
          chaptersCompleted['ch' + ci] = ci <= chCount;
        }

        importData = {
          studentInfo: {
            studentId: studentId,
            name: name,
            email: email,
            classCode: classCode
          },
          chaptersCompleted: chaptersCompleted,
          chapterScores: chapterScores,
          pblProjects: pblProjects,
          dimensionScores: dimensionScores,
          aiConversations: aiConversations,
          discussionPosts: discussionPosts,
          pretest: { score: pretestScore, taken: pretestScore != null, date: null },
          posttest: { score: posttestScore, taken: posttestScore != null, date: null },
          questionHistory: [],
          milestones: {},
          exportDate: new Date().toISOString(),
          version: 'feishu-v1'
        };
      }

      // Import using existing import logic
      try {
        var match = findOrCreateStudentFromImport(importData);
        var isNew = match.matchType === 'new';
        var applied = applyImportDataToStudent(match.matchedId, importData, isNew);

        var entry = {
          name: applied.name,
          studentId: applied.studentId,
          matchType: match.matchType,
          chaptersCompleted: applied.chaptersCompleted,
          questions: applied.questions,
          pblProjects: applied.pblProjects,
          aiConversations: applied.aiConversations
        };

        summary.success.push(entry);
        if (isNew) {
          summary.created.push(entry);
        } else {
          summary.updated.push(entry);
        }
      } catch(err) {
        summary.failed.push({
          studentId: (fields['学生ID'] || fields['学号'] || 'unknown'),
          name: fields['学生姓名'] || 'Unknown',
          reason: err.message
        });
      }
    }

    // Refresh student list
    v7RefreshStudentStats();

    var statusMsg = 'Imported ' + summary.success.length + ' students from Feishu';
    statusMsg += ' (' + summary.created.length + ' new, ' + summary.updated.length + ' updated)';
    if (summary.failed.length > 0) {
      statusMsg += ', ' + summary.failed.length + ' failed';
    }
    showAdminFeishuStatus(statusMsg, summary.failed.length > 0 ? 'info' : 'success');

    // If we're on students page, refresh it
    if (AdminState.currentPage === 'students') {
      renderStudentListV7(document.getElementById('contentArea'));
    }
  } catch(err) {
    console.error('Feishu import error:', err);
    showAdminFeishuStatus('Import failed: ' + err.message, 'error');
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = '\u2193 Import from Feishu'; }
  }
}

