const DIMENSIONS = ["clarity", "precision", "accuracy", "relevance", "consistency", "logicalCorrectness", "completeness", "fairness"];
const DIMENSION_NAMES = {"clarity": "Clarity", "precision": "Precision", "accuracy": "Accuracy", "relevance": "Relevance", "consistency": "Consistency", "logicalCorrectness": "Logical Correctness", "completeness": "Completeness", "fairness": "Fairness"};



// =========================================
// ADMIN APP
// =========================================

// =========================================
// STUDENT DATA SYNC FROM LOCALSTORAGE
// =========================================
var STUDENT_STORAGE_KEY = "ctp_student";
var lastSyncTime = 0;
var lastSyncDataHash = "";

function syncStudentData() {
  try {
    var saved = localStorage.getItem(STUDENT_STORAGE_KEY);
    if (!saved) return false;
    
    // Quick hash check to avoid unnecessary re-renders
    var hash = saved.length + "_" + saved.slice(-20);
    if (hash === lastSyncDataHash) return false;
    lastSyncDataHash = hash;
    
    var studentData = JSON.parse(saved);
    
    // Find and update stu_001 (active student)
    for (var i = 0; i < MOCK_STUDENTS.length; i++) {
      if (MOCK_STUDENTS[i].id === "stu_001") {
        var s = MOCK_STUDENTS[i];
        s.name = studentData.name || s.name;
        s.email = studentData.email || s.email;
        
        // Update scores from question history
        if (studentData.questionHistory && studentData.questionHistory.length > 0) {
          s.questionCount = studentData.questionHistory.length;
          
          // Calculate dimension scores with difficulty weighting
          var dimCorrectW = {};
          var dimTotalW = {};
          var dimAttempts = {};
          var dims = ["clarity","precision","accuracy","relevance","consistency","logicalCorrectness","completeness","fairness"];
          for (var d = 0; d < dims.length; d++) {
            dimCorrectW[dims[d]] = 0;
            dimTotalW[dims[d]] = 0;
            dimAttempts[dims[d]] = 0;
          }
          
          var wMap = { basic: 1, intermediate: 2, advanced: 3 };
          
          for (var h = 0; h < studentData.questionHistory.length; h++) {
            var hist = studentData.questionHistory[h];
            if (!hist.dimension || dims.indexOf(hist.dimension) === -1) continue;
            var w = wMap[hist.difficulty] || 1;
            dimTotalW[hist.dimension] += w;
            dimAttempts[hist.dimension]++;
            if (hist.correct) dimCorrectW[hist.dimension] += w;
          }
          
          for (var dd = 0; dd < dims.length; dd++) {
            s.dimensionScores[dims[dd]] = dimTotalW[dims[dd]] > 0 
              ? Math.round((dimCorrectW[dims[dd]] / dimTotalW[dims[dd]]) * 100) / 10 
              : 0;
          }
        }
        
        // Pre/post test scores
        if (studentData.pretestScore !== undefined && studentData.pretestScore !== null) {
          s.pretestScore = Math.round(studentData.pretestScore);
        }
        if (studentData.posttestScore !== undefined && studentData.posttestScore !== null) {
          s.posttestScore = Math.round(studentData.posttestScore);
        }
        if (studentData.pretestTaken !== undefined) s.pretestTaken = studentData.pretestTaken;
        if (studentData.posttestTaken !== undefined) s.posttestTaken = studentData.posttestTaken;
        
        // Chapter completion
        if (studentData.chaptersCompleted) {
          s.chaptersCompleted = s.chaptersCompleted || {};
          for (var key in studentData.chaptersCompleted) {
            if (studentData.chaptersCompleted.hasOwnProperty(key)) {
              s.chaptersCompleted[key] = studentData.chaptersCompleted[key];
            }
          }
        }
        if (studentData.chapterScores) {
          s.chapterScores = s.chapterScores || {};
          for (var k2 in studentData.chapterScores) {
            if (studentData.chapterScores.hasOwnProperty(k2)) {
              s.chapterScores[k2] = studentData.chapterScores[k2];
            }
          }
        }
        
        // Last activity
        if (studentData.lastActivity) {
          var d = new Date(studentData.lastActivity);
          s.lastActivity = d.toISOString().split("T")[0];
        }
        
        lastSyncTime = Date.now();
        return true;
      }
    }
  } catch(e) {
    console.warn("Sync student data failed:", e);
  }
  return false;
}

function autoSyncData() {
  var changed = syncStudentData();
  if (changed && AdminState.currentPage) {
    renderPage(AdminState.currentPage);
  }
}



