var TEACHER_AI_STATE = {
  conversation: [],
  currentScenario: null,
  scenarioResponses: [],
  responseIndex: 0,
  isOpen: false
};


var AdminState = {
  currentPage: "dashboard",
  selectedStudent: null,
  searchQuery: ""
};

document.querySelectorAll(".nav-item").forEach(function(item) {
  item.addEventListener("click", function() {
    var page = item.dataset.page;
    navigateTo(page);
  });
});

function navigateTo(page) {
  AdminState.currentPage = page;
  document.querySelectorAll(".nav-item").forEach(function(i) { i.classList.remove("active"); });
  var navItem = document.querySelector('[data-page="' + page + '"]');
  if (navItem) navItem.classList.add("active");
  
  var titles = {
    dashboard: "Dashboard",
    classes: "Class Management",
    students: "Student Management",
    analytics: "Class Analytics",
    course: "Course Management",
    questions: "Question Bank",
    settings: "Settings",
    pbl: "PBL Projects"
  };
  document.getElementById("topbarTitle").textContent = titles[page] || page;
  renderPage(page);
}

function renderPage(page) {
  var area = document.getElementById("contentArea");
  // Update class filter dropdown on each page render
  updateClassFilterDropdown();
  switch(page) {
    case "dashboard": renderAdminDashboardV7(area); break;
    case "classes": renderClassManagement(area); break;
    case "students": renderStudentListV7(area); break;
    case "analytics": renderClassAnalyticsV7(area); break;
    case "course": renderCourseManagement(area); break;
    case "questions": renderQuestionBank(area); break;
    case "settings": renderSettingsV7(area); break;
    case "pbl": renderAdminPBL(area); break;
    default: area.innerHTML = "<p>Page not found</p>";
  }
}

// =========================================
// DASHBOARD
// =========================================
function renderAdminDashboard(area) {
  var total = MOCK_STUDENTS.length;
  var active = MOCK_STUDENTS.filter(function(s) { return s.questionCount > 0; }).length;
  var completedCh1 = MOCK_STUDENTS.filter(function(s) { return s.chaptersCompleted.ch1; }).length;
  var completedPost = MOCK_STUDENTS.filter(function(s) { return s.posttestTaken; }).length;
  
  var avgPretest = 0, postCount = 0, avgPost = 0;
  var avgImprovement = 0;
  MOCK_STUDENTS.forEach(function(s) {
    if (s.pretestTaken) { avgPretest += s.pretestScore; postCount++; }
    if (s.posttestTaken) avgPost += s.posttestScore;
    if (s.pretestTaken && s.posttestTaken) avgImprovement += (s.posttestScore - s.pretestScore);
  });
  avgPretest = postCount > 0 ? Math.round(avgPretest / postCount) : 0;
  var postStudents = MOCK_STUDENTS.filter(function(s) { return s.posttestTaken; });
  avgPost = postStudents.length > 0 ? Math.round(avgPost / postStudents.length) : 0;
  avgImprovement = postStudents.length > 0 ? Math.round(avgImprovement / postStudents.length) : 0;

  var html = '';
  html += '<h1 class="page-title">Instructor Dashboard</h1>';
  html += '<p class="page-subtitle">Overview of your critical thinking class</p>';

  html += '<div class="grid-4 mb-16">';
  html += '<div class="stat-card"><div class="stat-label">Total Students</div><div class="stat-value">' + total + '</div><div class="stat-change up">' + active + ' active</div></div>';
  html += '<div class="stat-card"><div class="stat-label">Avg. Pretest Score</div><div class="stat-value">' + avgPretest + '%</div><div class="stat-change down">baseline</div></div>';
  html += '<div class="stat-card"><div class="stat-label">Avg. Post-test Score</div><div class="stat-value">' + avgPost + '%</div><div class="stat-change up">' + (avgImprovement > 0 ? '+' + avgImprovement + '% improvement' : 'n/a') + '</div></div>';
  html += '<div class="stat-card"><div class="stat-label">Chapter 1 Complete</div><div class="stat-value">' + completedCh1 + '/' + total + '</div><div class="stat-change up">' + Math.round(completedCh1/total*100) + '% completion</div></div>';
  html += '</div>';

  html += '<div class="grid-2">';
  html += '<div class="card"><div class="card-header"><div class="card-title">Recent Activity</div></div><div class="card-body">';
  
  // Sort by last activity
  var recent = MOCK_STUDENTS.slice().sort(function(a, b) {
    return new Date(b.lastActivity) - new Date(a.lastActivity);
  }).slice(0, 5);
  
  recent.forEach(function(s) {
    html += '<div style="display:flex; justify-content:space-between; align-items:center; padding:10px 0; border-bottom:1px solid var(--border);">';
    html += '<div style="display:flex; align-items:center; gap:10px;">';
    html += '<div style="width:36px;height:36px;border-radius:50%;background:linear-gradient(135deg,var(--accent),var(--success));display:flex;align-items:center;justify-content:center;color:#fff;font-weight:600;font-size:13px;">' + s.name.charAt(0) + '</div>';
    html += '<div><div style="font-size:13px;font-weight:500;">' + s.name + '</div>';
    html += '<div style="font-size:11px;color:var(--text-secondary);">' + s.questionCount + ' questions answered</div></div></div>';
    html += '<div style="font-size:11px;color:var(--text-muted);">' + s.lastActivity + '</div>';
    html += '</div>';
  });
  
  html += '</div></div>';

  html += '<div class="card"><div class="card-header"><div class="card-title">Students Needing Attention</div></div><div class="card-body">';
  
  var needsHelp = MOCK_STUDENTS.filter(function(s) {
    return (s.pretestTaken && s.pretestScore < 60) || s.questionCount < 20;
  });
  
  if (needsHelp.length === 0) {
    html += '<p class="text-muted text-sm">All students are doing well!</p>';
  } else {
    needsHelp.slice(0, 5).forEach(function(s) {
      var reason = s.questionCount < 20 ? 'Low engagement' : 'Pretest score low';
      html += '<div style="display:flex; justify-content:space-between; align-items:center; padding:10px 0; border-bottom:1px solid var(--border);">';
      html += '<div><div style="font-size:13px;font-weight:500;">' + s.name + '</div>';
      html += '<div style="font-size:11px;color:var(--danger);">' + reason + '</div></div>';
      html += '<button class="btn btn-outline btn-sm" onclick="viewStudent(\'' + s.id + '\')">View</button>';
      html += '</div>';
    });
  }
  
  html += '</div></div>';
  html += '</div>';

  // Class radar (average)
  html += '<div class="card"><div class="card-header"><div class="card-title">Class Average - Skill Radar</div></div><div class="card-body">';
  
  var avgDims = {};
  DIMENSIONS.forEach(function(dim) {
    var total = 0, count = 0;
    MOCK_STUDENTS.forEach(function(s) {
      if (s.questionCount > 0) {
        total += s.dimensionScores[dim];
        count++;
      }
    });
    avgDims[dim] = count > 0 ? total / count : 0;
  });
  
  var avgScores = DIMENSIONS.map(function(d) { return avgDims[d]; });
  var radarSvg = generateRadarSVG(avgScores, DIMENSIONS.map(function(d) { return DIMENSION_NAMES[d]; }), 340);
  html += '<div style="text-align:center;">' + radarSvg + '</div>';
  html += '</div></div>';

  area.innerHTML = html;
}

// =========================================
// STUDENT LIST
// =========================================
function renderStudentList(area) {
  var html = '';
  html += '<h1 class="page-title">Student Management</h1>';
  html += '<p class="page-subtitle">View and manage all students in your class</p>';
  
  html += '<div class="card"><div class="card-header">';
  html += '<div class="card-title">All Students (' + MOCK_STUDENTS.length + ')</div>';
  html += '<input type="text" class="search-box" placeholder="Search students..." oninput="filterStudents(this.value)">';
  html += '</div>';
  html += '<div style="overflow-x:auto;">';
  html += '<table class="data-table" id="studentTable"><thead><tr>';
  html += '<th>Student</th><th>Email</th><th>Pretest</th><th>Post-test</th>';
  html += '<th>Improvement</th><th>Questions</th><th>Ch. 1</th><th>Ch. 2</th><th>Last Active</th><th>Action</th>';
  html += '</tr></thead><tbody id="studentTableBody">';
  
  MOCK_STUDENTS.forEach(function(s) {
    var preBadge = s.pretestTaken 
      ? '<span class="badge ' + (s.pretestScore >= 70 ? 'badge-success' : s.pretestScore >= 50 ? 'badge-warning' : 'badge-danger') + '">' + s.pretestScore + '%</span>'
      : '<span class="badge badge-muted">Not taken</span>';
    var postBadge = s.posttestTaken
      ? '<span class="badge ' + (s.posttestScore >= 70 ? 'badge-success' : s.posttestScore >= 50 ? 'badge-warning' : 'badge-danger') + '">' + s.posttestScore + '%</span>'
      : '<span class="badge badge-muted">Not taken</span>';
    var improvement = s.pretestTaken && s.posttestTaken
      ? (s.posttestScore - s.pretestScore > 0 ? '+' : '') + (s.posttestScore - s.pretestScore)
      : '—';
    var ch1Badge = s.chaptersCompleted.ch1 
      ? '<span class="badge badge-success">Done</span>' 
      : '<span class="badge badge-warning">In Progress</span>';
    var ch2Badge = s.chaptersCompleted.ch2
      ? '<span class="badge badge-success">Done</span>' 
      : s.chaptersCompleted.ch1 ? '<span class="badge badge-warning">In Progress</span>' : '<span class="badge badge-muted">Not Started</span>';
    
    html += '<tr data-id="' + s.id + '" onclick="viewStudent(\'' + s.id + '\')">';
    html += '<td><div style="display:flex;align-items:center;gap:10px;">';
    html += '<div style="width:32px;height:32px;border-radius:50%;background:linear-gradient(135deg,var(--accent),var(--success));display:flex;align-items:center;justify-content:center;color:#fff;font-weight:600;font-size:12px;">' + s.name.charAt(0) + '</div>';
    html += '<span style="font-weight:500;">' + s.name + '</span></div></td>';
    html += '<td>' + s.email + '</td>';
    html += '<td>' + preBadge + '</td>';
    html += '<td>' + postBadge + '</td>';
    html += '<td class="' + (improvement > 0 ? 'text-success' : improvement < 0 ? 'text-danger' : '') + '">' + improvement + '</td>';
    html += '<td>' + s.questionCount + '</td>';
    html += '<td>' + ch1Badge + '</td>';
    html += '<td>' + ch2Badge + '</td>';
    html += '<td class="text-sm text-muted">' + s.lastActivity + '</td>';
    html += '<td><button class="btn btn-outline btn-sm" onclick="event.stopPropagation(); viewStudent(\'' + s.id + '\')">Details</button></td>';
    html += '</tr>';
  });

  html += '</tbody></table></div></div>';

  area.innerHTML = html;
}

function filterStudents(query) {
  AdminState.searchQuery = query.toLowerCase();
  var rows = document.querySelectorAll('#studentTableBody tr');
  rows.forEach(function(row) {
    var name = row.textContent.toLowerCase();
    row.style.display = name.indexOf(AdminState.searchQuery) !== -1 ? '' : 'none';
  });
}


// =========================================
// PBL PROJECTS (ADMIN)
// =========================================

var ADMIN_PBL_TAB = 'overview';

function renderAdminPBL(area) {
  var html = '';
  html += '<h1 class="page-title">Capstone PBL Management</h1>';
  html += '<p class="page-subtitle">Monitor student project progress and manage PBL portfolios</p>';
  
  html += '<div class="tabs">';
  html += '<div class="tab ' + (ADMIN_PBL_TAB === 'overview' ? 'active' : '') + '" onclick="switchAdminPBLTab(\'overview\')">PBL Overview</div>';
  html += '<div class="tab ' + (ADMIN_PBL_TAB === 'projects' ? 'active' : '') + '" onclick="switchAdminPBLTab(\'projects\')">Project Details</div>';
  html += '<div class="tab ' + (ADMIN_PBL_TAB === 'gallery' ? 'active' : '') + '" onclick="switchAdminPBLTab(\'gallery\')">Gallery Management</div>';
  html += '<div class="tab ' + (ADMIN_PBL_TAB === 'forum' ? 'active' : '') + '" onclick="switchAdminPBLTab(\'forum\')">Forum Management</div>';
  html += '</div>';
  
  if (ADMIN_PBL_TAB === 'overview') {
    html += renderAdminPBLOverview();
  } else if (ADMIN_PBL_TAB === 'projects') {
    html += renderAdminPBLProjects();
  } else if (ADMIN_PBL_TAB === 'forum') {
    html += renderAdminForumTab();
  } else {
    html += renderAdminPBLGallery();
  }
  
  area.innerHTML = html;
}

function switchAdminPBLTab(tab) {
  ADMIN_PBL_TAB = tab;
  renderAdminPBL(document.getElementById('contentArea'));
  if (typeof attachAdminForumListeners === 'function') {
    setTimeout(attachAdminForumListeners, 10);
  }
}

function renderAdminPBLOverview() {
  var total = MOCK_STUDENTS.length;
  
  // Capstone project distribution
  var projectDist = {};
  var projectKeys = Object.keys(PBL_CAPSTONE_PROJECTS);
  projectKeys.forEach(function(pid) { projectDist[pid] = 0; });
  
  var totalMilestonesCompleted = 0;
  var totalMilestonesPossible = 0;
  var allCompletedProjects = 0;
  var ch1Started = 0, ch2Started = 0, ch3Started = 0, ch4Started = 0, ch5Started = 0, ch6Started = 0, ch7Started = 0, ch8Started = 0, ch9Started = 0, ch10Started = 0;
  var ch1Completed = 0, ch2Completed = 0, ch3Completed = 0, ch4Completed = 0, ch5Completed = 0, ch6Completed = 0, ch7Completed = 0, ch8Completed = 0, ch9Completed = 0, ch10Completed = 0;
  var capstoneSelectedCount = 0;
  
  MOCK_STUDENTS.forEach(function(s) {
    if (s.capstoneProjectId && s.capstoneSelected) {
      capstoneSelectedCount++;
      projectDist[s.capstoneProjectId] = (projectDist[s.capstoneProjectId] || 0) + 1;
    }
    
    if (s.milestones) {
      ['ch1','ch2','ch3','ch4','ch5','ch6','ch7','ch8','ch9','ch10'].forEach(function(ch, idx) {
        var ms = s.milestones[ch];
        if (ms && ms.status !== 'locked') {
          if (ch === 'ch1') ch1Started++;
          if (ch === 'ch2') ch2Started++;
          if (ch === 'ch3') ch3Started++;
          if (ch === 'ch4') ch4Started++;
          if (ch === 'ch5') ch5Started++;
          if (ch === 'ch6') ch6Started++;
          if (ch === 'ch7') ch7Started++;
          if (ch === 'ch8') ch8Started++;
          if (ch === 'ch9') ch9Started++;
          if (ch === 'ch10') ch10Started++;
        }
        if (ms && ms.status === 'completed') {
          if (ch === 'ch1') ch1Completed++;
          if (ch === 'ch2') ch2Completed++;
          if (ch === 'ch3') ch3Completed++;
          if (ch === 'ch4') ch4Completed++;
          if (ch === 'ch5') ch5Completed++;
          if (ch === 'ch6') ch6Completed++;
          if (ch === 'ch7') ch7Completed++;
          if (ch === 'ch8') ch8Completed++;
          if (ch === 'ch9') ch9Completed++;
          if (ch === 'ch10') ch10Completed++;
          totalMilestonesCompleted++;
        }
      });
      totalMilestonesPossible += 10;
      
      // Check if all 10 milestones completed
      var allDone = ['ch1','ch2','ch3','ch4','ch5','ch6','ch7','ch8','ch9','ch10'].every(function(ch) {
        return s.milestones[ch] && s.milestones[ch].status === 'completed';
      });
      if (allDone) allCompletedProjects++;
    }
  });
  
  var avgMilestonesPerStudent = totalMilestonesPossible > 0 ? (totalMilestonesCompleted / total).toFixed(1) : 0;
  var overallCompletionPct = totalMilestonesPossible > 0 ? Math.round(totalMilestonesCompleted / totalMilestonesPossible * 100) : 0;
  
  var html = '';
  
  // Stats row
  html += '<div class="grid-4 mb-16">';
  html += '<div class="stat-card"><div class="stat-label">Projects Selected</div><div class="stat-value">' + capstoneSelectedCount + '/' + total + '</div><div class="stat-change up">' + Math.round(capstoneSelectedCount/total*100) + '% selected</div></div>';
  html += '<div class="stat-card"><div class="stat-label">Milestones Completed</div><div class="stat-value">' + totalMilestonesCompleted + '</div><div class="stat-change up">' + overallCompletionPct + '% overall</div></div>';
  html += '<div class="stat-card"><div class="stat-label">Avg. Milestones</div><div class="stat-value">' + avgMilestonesPerStudent + '</div><div class="stat-change up">per student</div></div>';
  html += '<div class="stat-card"><div class="stat-label">Final Projects Done</div><div class="stat-value">' + allCompletedProjects + '</div><div class="stat-change ' + (allCompletedProjects/total >= 0.3 ? 'up' : 'down') + '">' + Math.round(allCompletedProjects/total*100) + '% completion</div></div>';
  html += '</div>';
  
  // Project distribution + milestone progress
  html += '<div class="grid-2">';
  
  // Project distribution card
  html += '<div class="card"><div class="card-header"><div class="card-title">Project Theme Distribution</div></div><div class="card-body">';
  projectKeys.forEach(function(pid) {
    var p = PBL_CAPSTONE_PROJECTS[pid];
    var count = projectDist[pid] || 0;
    var pct = total > 0 ? Math.round(count / total * 100) : 0;
    html += '<div class="progress-item">';
    html += '<div class="progress-label"><span style="margin-right:8px;">' + p.icon + '</span>' + p.title + '</div>';
    html += '<div class="progress-track"><div class="progress-bar-fill" style="width:' + pct + '%;"></div></div>';
    html += '<div class="progress-value">' + count + ' (' + pct + '%)</div>';
    html += '</div>';
  });
  html += '</div></div>';
  
  // Milestone progress card
  html += '<div class="card"><div class="card-header"><div class="card-title">Milestone Progress</div></div><div class="card-body">';
  var milestoneData = [
    { ch: 'ch1', label: 'M1: Critical Thinking Standards', started: ch1Started, completed: ch1Completed },
    { ch: 'ch2', label: 'M2: Argument Recognition', started: ch2Started, completed: ch2Completed },
    { ch: 'ch3', label: 'M3: Logical Concepts', started: ch3Started, completed: ch3Completed },
    { ch: 'ch4', label: 'M4: Language Analysis', started: ch4Started, completed: ch4Completed },
    { ch: 'ch5', label: 'M5: Fallacy Detection I', started: ch5Started, completed: ch5Completed },
    { ch: 'ch6', label: 'M6: Fallacy Detection II', started: ch6Started, completed: ch6Completed },
    { ch: 'ch7', label: 'M7: Argument Analysis', started: ch7Started, completed: ch7Completed },
    { ch: 'ch8', label: 'M8: Argument Evaluation', started: ch8Started, completed: ch8Completed },
    { ch: 'ch9', label: 'M9: Categorical Logic', started: ch9Started, completed: ch9Completed },
    { ch: 'ch10', label: 'M10: Propositional Logic', started: ch10Started, completed: ch10Completed },
  ];
  milestoneData.forEach(function(m) {
    var startPct = total > 0 ? Math.round(m.started / total * 100) : 0;
    var compPct = total > 0 ? Math.round(m.completed / total * 100) : 0;
    html += '<div class="progress-item">';
    html += '<div class="progress-label">' + m.label + '</div>';
    html += '<div class="progress-track"><div class="progress-bar-fill" style="width:' + compPct + '%; background:linear-gradient(90deg,var(--success),#2ecc71);"></div></div>';
    html += '<div class="progress-value">' + m.completed + '/' + m.started + ' done</div>';
    html += '</div>';
  });
  html += '</div></div>';
  html += '</div>';
  
  // Class comparison (if multiple classes)
  var classes = {};
  MOCK_STUDENTS.forEach(function(s) {
    if (!classes[s.classCode]) classes[s.classCode] = { total: 0, milestones: 0, completed: 0 };
    classes[s.classCode].total++;
    if (s.milestones) {
      ['ch1','ch2','ch3','ch4','ch5','ch6','ch7','ch8','ch9','ch10'].forEach(function(ch) {
        if (s.milestones[ch] && s.milestones[ch].status === 'completed') classes[s.classCode].milestones++;
      });
      var allDone = ['ch1','ch2','ch3','ch4','ch5','ch6','ch7','ch8','ch9','ch10'].every(function(ch) {
        return s.milestones[ch] && s.milestones[ch].status === 'completed';
      });
      if (allDone) classes[s.classCode].completed++;
    }
  });
  
  if (Object.keys(classes).length > 1) {
    html += '<div class="card mt-16"><div class="card-header"><div class="card-title">Class Comparison</div></div><div class="card-body">';
    html += '<div class="progress-item"><div style="display:grid;grid-template-columns:120px 1fr 80px;gap:12px;align-items:center;width:100%;">';
    Object.keys(classes).forEach(function(cls) {
      var c = classes[cls];
      var avg = c.total > 0 ? (c.milestones / (c.total * 4) * 100).toFixed(0) : 0;
      html += '<div style="font-weight:600;">Class ' + cls + '</div>';
      html += '<div class="progress-track"><div class="progress-bar-fill" style="width:' + avg + '%;"></div></div>';
      html += '<div class="progress-value" style="text-align:right;">' + avg + '% avg</div>';
    });
    html += '</div></div>';
    html += '</div></div>';
  }
  
  return html;
}

function renderAdminPBLProjects() {
  var html = '';
  
  html += '<div class="card mb-16"><div class="card-header"><div class="card-title">Student Capstone Projects</div>';
  html += '<span class="text-sm text-muted">All students and their capstone project progress</span></div><div class="card-body">';
  
  if (MOCK_STUDENTS.length === 0) {
    html += '<p class="text-sm text-muted">No students yet.</p>';
  } else {
    html += '<table class="data-table"><thead><tr>';
    html += '<th>Student</th><th>Class</th><th>Project Theme</th><th>Milestones</th><th>Progress</th><th>Final Project</th><th>Action</th>';
    html += '</tr></thead><tbody>';
    
    MOCK_STUDENTS.forEach(function(s) {
      var projectName = 'Not selected';
      var projectIcon = '';
      if (s.capstoneProjectId && PBL_CAPSTONE_PROJECTS[s.capstoneProjectId]) {
        projectName = PBL_CAPSTONE_PROJECTS[s.capstoneProjectId].title;
        projectIcon = PBL_CAPSTONE_PROJECTS[s.capstoneProjectId].icon + ' ';
      }
      
      var progress = adminGetMilestoneProgress(s);
      var allDone = progress.completed === 4;
      var progressLabel = progress.completed + '/' + progress.total;
      
      // Get milestones detail
      var msDetails = [];
      if (s.milestones) {
        ['ch1','ch2','ch3','ch4','ch5','ch6','ch7','ch8','ch9','ch10'].forEach(function(ch) {
          var ms = s.milestones[ch];
          if (ms && ms.status === 'completed') msDetails.push('&#10003; ' + ch.toUpperCase());
          else if (ms && ms.status !== 'locked') msDetails.push('&#9679; ' + ch.toUpperCase());
          else msDetails.push('&#128274; ' + ch.toUpperCase());
        });
      }
      
      html += '<tr>';
      html += '<td>' + s.name + '</td>';
      html += '<td><span class="badge badge-info">' + (s.classCode || '-') + '</span></td>';
      html += '<td>' + projectIcon + projectName + '</td>';
      html += '<td>' + progressLabel + '</td>';
      html += '<td>';
      html += '<div style="display:inline-block;width:100px;vertical-align:middle;margin-right:8px;">';
      html += '<div class="progress-track" style="height:8px;margin:0;"><div class="progress-bar-fill" style="width:' + progress.pct + '%;"></div></div>';
      html += '</div>';
      html += '<span class="text-sm text-secondary">' + progress.pct + '%</span>';
      html += '</td>';
      html += '<td>' + (allDone ? '<span class="badge badge-success">Done</span>' : '<span class="badge badge-muted">In Progress</span>') + '</td>';
      html += '<td><button class="btn btn-outline btn-sm" data-student="' + s.id + '" onclick="adminViewStudentCapstone(this.dataset.student)">View</button></td>';
      html += '</tr>';
    });
    
    html += '</tbody></table>';
  }
  
  html += '</div></div>';
  
  return html;
}

function adminViewStudentCapstone(studentId) {
  var s = MOCK_STUDENTS.find(function(st) { return st.id === studentId; });
  if (!s) return;
  
  var projectName = 'Not selected';
  if (s.capstoneProjectId && PBL_CAPSTONE_PROJECTS[s.capstoneProjectId]) {
    projectName = PBL_CAPSTONE_PROJECTS[s.capstoneProjectId].icon + ' ' + PBL_CAPSTONE_PROJECTS[s.capstoneProjectId].title;
  }
  
  var progress = adminGetMilestoneProgress(s);
  var html = '';
  html += '<div class="modal-header"><div class="modal-title">' + s.name + ' - Capstone Project</div>';
  html += '<button class="modal-close" onclick="closePBLDetailModal()">&times;</button></div>';
  html += '<div class="modal-body">';
  
  html += '<div class="card mb-16"><div class="card-body">';
  html += '<div style="font-size:18px;font-weight:700;margin-bottom:8px;">' + projectName + '</div>';
  html += '<div class="text-secondary text-sm mb-12">Class: ' + (s.classCode || '-') + ' &middot; ' + progress.completed + '/' + progress.total + ' milestones completed</div>';
  html += '<div class="progress-track"><div class="progress-bar-fill" style="width:' + progress.pct + '%;"></div></div>';
  html += '</div></div>';
  
  // Milestones
  html += '<h4 style="margin-bottom:12px;">Milestones</h4>';
  var msLabels = {
    ch1: "M1: Critical Thinking Standards",
    ch2: "M2: Argument Recognition",
    ch3: "M3: Logical Concepts",
    ch4: "M4: Language Analysis",
    ch5: "M5: Fallacy Detection I",
    ch6: "M6: Fallacy Detection II",
    ch7: "M7: Argument Analysis",
    ch8: "M8: Argument Evaluation",
    ch9: "M9: Categorical Logic",
    ch10: "M10: Propositional Logic",
  };
  
  ['ch1','ch2','ch3','ch4','ch5','ch6','ch7','ch8','ch9','ch10'].forEach(function(ch) {
    var ms = s.milestones ? s.milestones[ch] : null;
    var status = ms ? ms.status : 'locked';
    var statusClass = status === 'completed' ? 'badge-success' : (status === 'available' || status === 'in_progress' ? 'badge-info' : 'badge-muted');
    var statusText = status.replace('_', ' ');
    
    html += '<div class="card mb-8"><div class="card-body" style="padding:12px 16px;">';
    html += '<div class="flex-between">';
    html += '<span style="font-weight:600;">' + msLabels[ch] + '</span>';
    html += '<span class="badge ' + statusClass + '">' + statusText + '</span>';
    html += '</div>';
    if (ms && ms.deliverable) {
      html += '<div class="text-sm text-secondary mt-8" style="max-height:60px;overflow:hidden;text-overflow:ellipsis;">' + ms.deliverable.substring(0, 150) + '...</div>';
    }
    html += '</div></div>';
  });
  
  // Final project
  var allDone = progress.completed === 4;
  html += '<div class="card mt-16" style="border:2px solid var(--primary);"><div class="card-header"><div class="card-title">Final Deliverable</div>';
  html += '<span class="badge ' + (allDone ? 'badge-success' : 'badge-muted') + '">' + (allDone ? 'Completed' : 'Not Yet') + '</span></div>';
  html += '<div class="card-body">';
  if (allDone) {
    html += '<p class="text-sm text-secondary mb-12">All milestones completed. Student has produced a full capstone project report.</p>';
    html += '<button class="btn btn-primary btn-sm">View Final Report</button>';
  } else {
    html += '<p class="text-sm text-secondary">Complete all 10 milestones to unlock the final deliverable.</p>';
  }
  html += '</div></div>';
  
  html += '</div>';
  
  var modal = document.getElementById('pblDetailModal') || document.getElementById('studentDetailModal');
  if (!modal) {
    // Create modal if not exists
    var modalEl = document.createElement('div');
    modalEl.id = 'pblDetailModal';
    modalEl.className = 'modal-overlay';
    modalEl.innerHTML = '<div class="modal" style="max-width:600px;"><div id="pblDetailContent"></div></div>';
    modalEl.onclick = function(e) { if (e.target === modalEl) closePBLDetailModal(); };
    document.body.appendChild(modalEl);
    modal = modalEl;
  }
  
  var contentEl = document.getElementById('pblDetailContent') || modal.querySelector('.modal');
  if (contentEl) contentEl.innerHTML = html;
  modal.style.display = 'flex';
}

function renderAdminPBLGallery() {
  var html = '';
  html += '<div class="card mb-16"><div class="card-header"><div class="card-title">Gallery Management</div>';
  html += '<span class="text-sm text-muted">Curate student works for public display</span></div><div class="card-body">';
  
  // Mock gallery data
  var galleryItems = [
    { student: 'Student C', project: 'Project 1', score: 9.1, featured: true, icon: '\ud83d\udca1' },
    { student: 'Student A', project: 'Project 1', score: 8.5, featured: true, icon: '\ud83e\udde0' },
    { student: 'Student E', project: 'Project 1', score: 8.0, featured: false, icon: '\ud83d\udcd6' },
    { student: 'Student B', project: 'Project 1', score: 7.2, featured: false, icon: '\ud83c\udfaf' },
    { student: 'Student C', project: 'Project 2', score: 8.9, featured: true, icon: '\ud83d\udd0d' },
    { student: 'Student A', project: 'Project 2', score: 8.2, featured: false, icon: '\ud83d\udccb' },
    { student: 'Student F', project: 'Project 1', score: 7.5, featured: false, icon: '\ud83c\udfdb\ufe0f' },
    { student: 'Student D', project: 'Project 2', score: 7.0, featured: false, icon: '\ud83d\udcac' }
  ];
  
  html += '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px;">';
  galleryItems.forEach(function(item, idx) {
    html += '<div style="background:#fff;border:1px solid var(--border);border-radius:8px;overflow:hidden;">';
    html += '<div style="height:120px;background:linear-gradient(135deg,#e8f4fd,#d4e9fa);display:flex;align-items:center;justify-content:center;font-size:40px;">' + item.icon + '</div>';
    html += '<div style="padding:10px 12px;">';
    html += '<div style="font-size:12px;font-weight:500;">' + item.student + '</div>';
    html += '<div style="font-size:11px;color:var(--text-muted);margin-bottom:6px;">' + item.project + '</div>';
    html += '<div style="display:flex;justify-content:space-between;align-items:center;">';
    html += '<span style="font-size:12px;font-weight:600;color:var(--success);">' + item.score + '/10</span>';
    html += item.featured 
      ? '<span style="font-size:10px;padding:2px 6px;background:#fef3e2;color:var(--warning);border-radius:8px;font-weight:600;">Featured</span>'
      : '<button class="btn btn-sm btn-outline" style="font-size:10px;padding:2px 8px;" onclick="this.textContent=\'Featured\';this.style.background=\'#fef3e2\';this.style.color=\'#f39c12\';this.style.borderColor=\'#f39c12\';">Feature</button>';
    html += '</div></div></div>';
  });
  html += '</div>';
  
  html += '</div></div>';
  return html;
}

function viewStudentPBL(chKey) {
  var s = AdminState.selectedStudent;
  if (!s || !s.pblProjects || !s.pblProjects[chKey]) return;
  viewStudentPBLLarge(s.id, chKey);
}

function viewStudentPBLLarge(studentId, chKey) {
  PBL_VIEW_CH = chKey;
  
  // Ensure student has pblProjects data
  ensureMockPBLData();
  
  var s = MOCK_STUDENTS.find(function(stu) { return stu.id === studentId; });
  if (!s) return;
  
  // V7: If student has real data, merge it in
  var realData = v7AdminGetStudentData(studentId);
  if (realData && realData.pblProjects) {
    if (!s.pblProjects) s.pblProjects = {};
    for (var pk in realData.pblProjects) {
      if (realData.pblProjects.hasOwnProperty(pk)) {
        s.pblProjects[pk] = realData.pblProjects[pk];
      }
    }
  }
  
  if (!s.pblProjects || !s.pblProjects[chKey]) return;
  
  var p = s.pblProjects[chKey];
  var projectName = chKey === 'ch1' ? 'Project 1: Critical Thinking in Business Decisions' : 'Project 2: Argument Analysis in Marketing & Media';
  
  var html = '';
  html += '<div style="margin-bottom:16px; padding-bottom:12px; border-bottom:1px solid var(--border); display:flex; justify-content:space-between; align-items:center;">';
  html += '<div><div style="font-size:16px; font-weight:700;">' + s.name + ' — ' + projectName + '</div>';
  html += '<div style="font-size:12px; color:var(--text-secondary);">' + p.status.replace('_',' ') + ' | ' + (p.iterations||0) + ' iterations</div></div>';
  html += '<button class="btn btn-outline btn-sm" onclick="closePBLDetailModal()">Close</button>';
  html += '</div>';
  
  html += '<div class="grid-2">';
  
  // Knowledge Map
  html += '<div><h4 style="font-size:13px; margin-bottom:8px;">Knowledge Map</h4>';
  var km = p.finalKnowledgeMap || p.knowledgeMap || { nodes: [], links: [] };
  html += '<div class="portfolio-kmap">';
  if (km.nodes && km.nodes.length > 0) {
    html += '<div style="position:absolute; top:10px; left:10px; font-size:11px; color:var(--text-muted); background:#fff; padding:2px 8px; border-radius:10px;">' + km.nodes.length + ' nodes, ' + (km.links?km.links.length:0) + ' links</div>';
    // Render simple nodes
    km.nodes.forEach(function(node, ni) {
      var x = typeof node.x === 'number' ? node.x : 20 + ni * 60;
      var y = typeof node.y === 'number' ? node.y : 20 + (ni % 3) * 50;
      x = Math.max(5, Math.min(280, x));
      y = Math.max(5, Math.min(170, y));
      html += '<div style="position:absolute; left:' + x + 'px; top:' + y + 'px; padding:4px 10px; background:#fff; border:1px solid var(--accent); border-radius:6px; font-size:10px; font-weight:500; z-index:2;">' + (node.label || 'Node') + '</div>';
    });
  } else {
    html += '<div style="display:flex;align-items:center;justify-content:center;height:100%;font-size:12px;color:var(--text-muted);">No knowledge map</div>';
  }
  html += '</div></div>';
  
  // Final Report
  html += '<div><h4 style="font-size:13px; margin-bottom:8px;">Final Report</h4>';
  var report = p.finalReport || (p.reportDrafts && p.reportDrafts.length > 0 ? p.reportDrafts[p.reportDrafts.length-1].text : '');
  if (report) {
    var wordCount = report.trim().split(/\s+/).length;
    html += '<div style="font-size:11px; color:var(--text-muted); margin-bottom:6px;">' + wordCount + ' words</div>';
    html += '<div class="portfolio-report">' + report + '</div>';
  } else {
    html += '<div class="portfolio-report" style="color:var(--text-muted);">No report submitted yet.</div>';
  }
  html += '</div>';
  html += '</div>'; // end grid-2
  
  // Score & feedback
  html += '<div class="grid-2 mt-16">';
  html += '<div><h4 style="font-size:13px; margin-bottom:8px;">AI Score</h4>';
  if (p.aiScore !== null) {
    html += '<div style="font-size:36px; font-weight:800; color:var(--accent);">' + p.aiScore.toFixed(1) + '<span style="font-size:16px; color:var(--text-muted);">/10</span></div>';
  } else {
    html += '<p class="text-sm text-muted">Not yet scored</p>';
  }
  html += '<div style="margin-top:12px;"><label style="font-size:11px; color:var(--text-secondary); display:block; margin-bottom:4px;">Manual Score Override</label>';
  html += '<input type="number" min="0" max="10" step="0.1" class="manual-score-input" id="manualScoreInput" placeholder="0-10" value="' + (p.aiScore || '') + '">';
  html += '<button class="btn btn-sm btn-outline" style="margin-left:6px;" onclick="applyManualScore(\'' + studentId + '\', \'' + chKey + '\')">Apply</button>';
  html += '</div></div>';
  
  html += '<div><h4 style="font-size:13px; margin-bottom:8px;">Instructor Feedback</h4>';
  html += '<textarea style="width:100%; min-height:80px; padding:8px; border:1px solid var(--border); border-radius:4px; font-size:12px; font-family:inherit; resize:vertical;" placeholder="Write your feedback for the student..." id="instructorFeedback">Great work on this project! Your analysis shows strong critical thinking.</textarea>';
  html += '<button class="btn btn-sm btn-primary" style="margin-top:8px;" onclick="saveInstructorFeedback()">Save Feedback</button>';
  html += '</div>';
  html += '</div>';
  
  // AI Feedback
  if (p.aiFeedback) {
    html += '<div class="mt-16"><h4 style="font-size:13px; margin-bottom:8px;">AI Detailed Feedback</h4>';
    html += '<div style="background:#f0f7fd; border:1px solid #b8dcf5; border-radius:6px; padding:12px; font-size:12px; line-height:1.6; color:var(--text-secondary);">' + p.aiFeedback + '</div>';
    html += '</div>';
  }
  
  // Iteration history
  if (p.reportDrafts && p.reportDrafts.length > 0) {
    html += '<div class="mt-16"><h4 style="font-size:13px; margin-bottom:8px;">Iteration History (' + p.reportDrafts.length + ' versions)</h4>';
    html += '<div style="display:flex; gap:8px; flex-wrap:wrap;">';
    p.reportDrafts.forEach(function(d, i) {
      var words = d.text.trim() ? d.text.trim().split(/\s+/).length : 0;
      html += '<div style="padding:6px 10px; background:#f8fafc; border-radius:4px; font-size:11px;">';
      html += 'V' + (i+1) + ': ' + words + 'w';
      html += '</div>';
    });
    html += '</div></div>';
  }
  
  // Create modal
  var modalHtml = '<div class="modal-overlay show" id="pblDetailModal">' +
    '<div class="modal" style="max-width:900px;">' +
    '<div class="modal-body" style="padding:20px;">' + html + '</div>' +
    '</div></div>';
  
  var existing = document.getElementById("pblDetailModal");
  if (existing) existing.remove();
  
  document.body.insertAdjacentHTML('beforeend', modalHtml);
  document.getElementById("pblDetailModal").addEventListener("click", function(e) {
    if (e.target === this) closePBLDetailModal();
  });
}

function closePBLDetailModal() {
  var modal = document.getElementById("pblDetailModal");
  if (modal) modal.remove();
}

function applyManualScore(studentId, chKey) {
  var s = MOCK_STUDENTS.find(function(stu) { return stu.id === studentId; });
  if (!s || !s.pblProjects || !s.pblProjects[chKey]) return;
  
  var input = document.getElementById('manualScoreInput');
  if (input) {
    var val = parseFloat(input.value);
    if (!isNaN(val) && val >= 0 && val <= 10) {
      s.pblProjects[chKey].aiScore = val;
      
      // V7: Also save to student data in localStorage
      var stuData = v7AdminGetStudentData(studentId);
      if (stuData && stuData.pblProjects && stuData.pblProjects[chKey]) {
        stuData.pblProjects[chKey].aiScore = val;
        v7AdminSaveStudentData(studentId, stuData);
      }
      
      alert('Score updated to ' + val.toFixed(1) + '/10');
    }
  }
}

function saveInstructorFeedback() {
  var textarea = document.getElementById('instructorFeedback');
  var studentId = AdminState.selectedStudent ? AdminState.selectedStudent.id : null;
  var chKey = PBL_VIEW_CH || 'ch1';
  
  if (textarea && studentId) {
    var feedback = textarea.value;
    // Save to mock student
    var s = MOCK_STUDENTS.find(function(stu) { return stu.id === studentId; });
    if (s && s.pblProjects && s.pblProjects[chKey]) {
      s.pblProjects[chKey].instructorFeedback = feedback;
    }
    
    // V7: Save to real student data
    var stuData = v7AdminGetStudentData(studentId);
    if (stuData && stuData.pblProjects && stuData.pblProjects[chKey]) {
      stuData.pblProjects[chKey].instructorFeedback = feedback;
      v7AdminSaveStudentData(studentId, stuData);
    }
  }
  
  alert('Instructor feedback saved!');
}

var PBL_VIEW_CH = 'ch1';

