// =========================================
// STUDENT DETAIL (Modal)
// =========================================
function viewStudent(studentId) {
  var s = MOCK_STUDENTS.find(function(stu) { return stu.id === studentId; });
  if (!s) return;
  
  AdminState.selectedStudent = s;
  showStudentModal(s);
}

function showStudentModal(s) {
  var recs = generateStudentRecommendations(s);
  var initials = s.name.split(' ').map(function(n){return n[0];}).join('').substring(0,2);
  
  var radarSvg = generateRadarSVG(
    DIMENSIONS.map(function(d){return s.dimensionScores[d];}),
    DIMENSIONS.map(function(d){return DIMENSION_NAMES[d];}),
    300
  );

  var html = '';
  html += '<div class="student-detail-header">';
  html += '<div class="student-detail-avatar">' + initials + '</div>';
  html += '<div style="flex:1;"><div class="student-detail-name">' + s.name + '</div>';
  html += '<div class="student-detail-email">' + s.email + '</div></div>';
  html += '<button class="btn btn-outline btn-sm" onclick="closeStudentModal()">Close</button>';
  html += '</div>';

  html += '<div class="grid-2">';
  
  // Left column: scores, radar
  html += '<div>';
  html += '<div style="margin-bottom:16px;"><h4 style="font-size:14px;margin-bottom:12px;">Performance Summary</h4>';
  html += '<div class="grid-2" style="gap:10px;">';
  html += '<div style="background:#f8fafc;padding:12px;border-radius:6px;text-align:center;">';
  html += '<div class="text-sm text-muted">Pretest</div>';
  html += '<div style="font-size:22px;font-weight:700;">' + (s.pretestTaken ? s.pretestScore + '%' : 'N/A') + '</div></div>';
  html += '<div style="background:#f8fafc;padding:12px;border-radius:6px;text-align:center;">';
  html += '<div class="text-sm text-muted">Post-test</div>';
  html += '<div style="font-size:22px;font-weight:700;">' + (s.posttestTaken ? s.posttestScore + '%' : 'N/A') + '</div></div>';
  html += '</div></div>';

  html += '<div style="margin-bottom:16px;"><h4 style="font-size:14px;margin-bottom:12px;">Skill Radar</h4>';
  html += '<div class="radar-container">' + radarSvg + '</div></div>';

  html += '<div><h4 style="font-size:14px;margin-bottom:12px;">Dimension Breakdown</h4>';
  var ranked = DIMENSIONS.map(function(d){return {name:DIMENSION_NAMES[d],score:s.dimensionScores[d]};})
    .sort(function(a,b){return b.score - a.score;});
  ranked.forEach(function(item) {
    var pct = Math.round(item.score / 10 * 100);
    html += '<div class="progress-item">';
    html += '<div class="progress-label">' + item.name + '</div>';
    html += '<div class="progress-track"><div class="progress-bar-fill" style="width:' + pct + '%;"></div></div>';
    html += '<div class="progress-value">' + item.score.toFixed(1) + '/10</div>';
    html += '</div>';
  });
  html += '</div>';
  html += '</div>';  // end left column

  // Right column: AI recommendations + activity
  html += '<div>';
  html += '<div style="margin-bottom:16px;"><h4 style="font-size:14px;margin-bottom:12px;">AI Recommendations</h4>';
  
  recs.forEach(function(rec) {
    html += '<div class="recommendation-card">';
    html += '<h4>&#128161; ' + rec.title + '</h4>';
    html += '<p>' + rec.text + '</p>';
    html += '</div>';
  });
  
  html += '</div>';

  html += '<div><h4 style="font-size:14px;margin-bottom:12px;">Learning Activity</h4>';
  html += '<div style="background:#f8fafc;padding:12px;border-radius:6px;">';
  html += '<div class="flex-between mb-8"><span class="text-sm text-secondary">Questions Answered</span><span class="text-sm font-600">' + s.questionCount + '</span></div>';
  html += '<div class="flex-between mb-8"><span class="text-sm text-secondary">Chapter 1</span><span class="text-sm font-600">' + (s.chaptersCompleted.ch1 ? 'Complete (' + s.chapterScores.ch1 + '%)' : 'In Progress') + '</span></div>';
  html += '<div class="flex-between mb-8"><span class="text-sm text-secondary">Chapter 2</span><span class="text-sm font-600">' + (s.chaptersCompleted.ch2 ? 'Complete (' + s.chapterScores.ch2 + '%)' : 'In Progress') + '</span></div>';
  html += '<div class="flex-between"><span class="text-sm text-secondary">Last Active</span><span class="text-sm font-600">' + s.lastActivity + '</span></div>';
  html += '</div></div>';
  // PBL Portfolio section
  html += '<div style="margin-top:20px;"><h4 style="font-size:14px;margin-bottom:12px;">PBL Portfolio</h4>';
  if (s.pblProjects) {
    var ch1Status = s.pblProjects.ch1 ? s.pblProjects.ch1.status : 'locked';
    var ch2Status = s.pblProjects.ch2 ? s.pblProjects.ch2.status : 'locked';
    html += '<div class="grid-2" style="gap:10px;">';
    html += '<div style="background:#f8fafc;padding:12px;border-radius:6px;">';
    html += '<div style="font-size:12px;font-weight:600;margin-bottom:4px;">Project 1: Business Decisions</div>';
    html += '<div style="font-size:11px;color:var(--text-muted);margin-bottom:6px;">Status: <span class="badge ' + (ch1Status==='completed'?'badge-success':ch1Status==='in_progress'?'badge-info':'badge-muted') + '">' + ch1Status.replace('_',' ') + '</span></div>';
    if (s.pblProjects.ch1 && s.pblProjects.ch1.aiScore !== null) {
      html += '<div style="font-size:18px;font-weight:700;color:var(--accent);">' + s.pblProjects.ch1.aiScore.toFixed(1) + '/10</div>';
    }
    html += '<button class="btn btn-outline btn-sm mt-8" style="font-size:11px;padding:3px 10px;" onclick="viewStudentPBL("ch1")">View Work</button>';
    html += '</div>';
    html += '<div style="background:#f8fafc;padding:12px;border-radius:6px;">';
    html += '<div style="font-size:12px;font-weight:600;margin-bottom:4px;">Project 2: Marketing Analysis</div>';
    html += '<div style="font-size:11px;color:var(--text-muted);margin-bottom:6px;">Status: <span class="badge ' + (ch2Status==='completed'?'badge-success':ch2Status==='in_progress'?'badge-info':'badge-muted') + '">' + ch2Status.replace('_',' ') + '</span></div>';
    if (s.pblProjects.ch2 && s.pblProjects.ch2.aiScore !== null) {
      html += '<div style="font-size:18px;font-weight:700;color:var(--accent);">' + s.pblProjects.ch2.aiScore.toFixed(1) + '/10</div>';
    }
    html += '<button class="btn btn-outline btn-sm mt-8" style="font-size:11px;padding:3px 10px;" onclick="viewStudentPBL("ch2")">View Work</button>';
    html += '</div></div>';
  } else {
    html += '<p class="text-sm text-muted">No PBL data available.</p>';
  }
  html += '</div>';

  html += '</div>';  // end right column

  html += '</div>';  // end grid-2

  // Create modal
  var modalHtml = '<div class="modal-overlay show" id="studentModal">' +
    '<div class="modal">' +
    '<div class="modal-header"><div class="modal-title">Student Details</div>' +
    '<button class="modal-close" onclick="closeStudentModal()">&times;</button></div>' +
    '<div class="modal-body">' + html + '</div>' +
    '</div></div>';
  
  // Remove existing modal
  var existing = document.getElementById("studentModal");
  if (existing) existing.remove();
  
  document.body.insertAdjacentHTML('beforeend', modalHtml);
  document.getElementById("studentModal").addEventListener("click", function(e) {
    if (e.target === this) closeStudentModal();
  });
}

function closeStudentModal() {
  var modal = document.getElementById("studentModal");
  if (modal) modal.remove();
}

function generateStudentRecommendations(s) {
  var recs = [];
  var dims = DIMENSIONS.slice().sort(function(a,b) { 
    return s.dimensionScores[a] - s.dimensionScores[b]; 
  });
  var weakest = dims[0];
  var strongest = dims[dims.length - 1];
  var firstName = s.name.split(' ')[0];

  // Weakest area
  if (s.questionCount > 0) {
    recs.push({
      title: "Focus on " + DIMENSION_NAMES[weakest],
      text: firstName + "'s weakest dimension is " + DIMENSION_NAMES[weakest] + " (" + s.dimensionScores[weakest].toFixed(1) + "/10). Assign targeted practice in this area. Consider additional examples or one-on-one discussion to strengthen understanding."
    });
  }

  // Strongest area
  if (s.questionCount > 0) {
    recs.push({
      title: "Leverage " + DIMENSION_NAMES[strongest] + " Strength",
      text: firstName + " shows strength in " + DIMENSION_NAMES[strongest] + " (" + s.dimensionScores[strongest].toFixed(1) + "/10). Encourage advanced-level exploration. Consider extension activities or peer teaching opportunities."
    });
  }

  // Progress
  if (s.pretestTaken && s.posttestTaken) {
    var imp = s.posttestScore - s.pretestScore;
    if (imp >= 15) {
      recs.push({
        title: "Excellent Progress (+"+imp+"%)",
        text: "Outstanding growth from pretest to post-test. " + firstName + " is clearly engaging with the material. Challenge with advanced question levels and original argument analysis projects."
      });
    } else if (imp >= 5) {
      recs.push({
        title: "Steady Improvement (+"+imp+"%)",
        text: "Good progress. Continue with targeted practice in weaker dimensions. Encourage more frequent short practice sessions for faster improvement."
      });
    } else {
      recs.push({
        title: "Minimal Progress",
        text: firstName + " has shown limited improvement. Review study habits and consider a different instructional approach. Check for motivation issues or difficulty with core concepts. One-on-one tutoring may help."
      });
    }
  }

  // Engagement
  if (s.questionCount < 20) {
    recs.push({
      title: "Low Engagement Alert",
      text: "Only " + s.questionCount + " questions answered. The student may be struggling with motivation or finding the material too difficult. Consider checking in about their experience and adjusting starting difficulty."
    });
  } else if (s.questionCount > 100) {
    recs.push({
      title: "High Engagement",
      text: firstName + " has completed " + s.questionCount + " questions — very engaged! This student is clearly motivated. Provide enrichment and consider assigning them as a peer helper for other students."
    });
  }

  // Chapter progress
  if (!s.chaptersCompleted.ch1) {
    recs.push({
      title: "Chapter 1 Incomplete",
      text: "Chapter 1 foundations not yet mastered. Ensure " + firstName + " understands the 8 standards and barriers before moving to Chapter 2 argument analysis."
    });
  } else if (!s.chaptersCompleted.ch2) {
    recs.push({
      title: "Chapter 2 Incomplete",
      text: "Chapter 2 (Recognizing Arguments) not yet completed. Encourage continued progress through argument identification practice."
    });
  }

  // Study strategy
  recs.push({
    title: "Study Strategy Recommendation",
    text: "Recommend active recall (self-quizzing) over passive rereading. Suggest 15-20 minute daily practice sessions with the Socratic AI tutor for guided questioning and deeper metacognitive engagement."
  });

  return recs.slice(0, 5);
}

