// CLASS ANALYTICS
// =========================================
function renderClassAnalytics(area) {
  var html = '';
  html += '<h1 class="page-title">Class Analytics</h1>';
  html += '<p class="page-subtitle">Aggregated performance data across all students</p>';

  html += '<div class="grid-3 mb-16">';
  var preAvg = 0, postAvg = 0, preCount = 0, postCount = 0;
  MOCK_STUDENTS.forEach(function(s) {
    if (s.pretestTaken) { preAvg += s.pretestScore; preCount++; }
    if (s.posttestTaken) { postAvg += s.posttestScore; postCount++; }
  });
  preAvg = preCount > 0 ? Math.round(preAvg / preCount) : 0;
  postAvg = postCount > 0 ? Math.round(postAvg / postCount) : 0;
  var avgImp = postCount > 0 && preCount > 0 ? postAvg - preAvg : 0;
  
  html += '<div class="stat-card"><div class="stat-label">Avg. Pretest Score</div><div class="stat-value">' + preAvg + '%</div></div>';
  html += '<div class="stat-card"><div class="stat-label">Avg. Post-test Score</div><div class="stat-value">' + postAvg + '%</div></div>';
  html += '<div class="stat-card"><div class="stat-label">Avg. Improvement</div><div class="stat-value text-success">+' + avgImp + '%</div></div>';
  html += '</div>';

  html += '<div class="grid-2">';
  html += '<div class="card"><div class="card-header"><div class="card-title">Class Average - 8 Dimensions</div></div>';
  html += '<div class="card-body">';
  
  var classDims = {};
  DIMENSIONS.forEach(function(dim) {
    var total = 0, count = 0;
    MOCK_STUDENTS.forEach(function(s) {
      if (s.questionCount > 0) { total += s.dimensionScores[dim]; count++; }
    });
    classDims[dim] = count > 0 ? total / count : 0;
  });
  
  var avgRadar = generateRadarSVG(
    DIMENSIONS.map(function(d){return classDims[d];}),
    DIMENSIONS.map(function(d){return DIMENSION_NAMES[d];}),
    320
  );
  html += '<div style="text-align:center;">' + avgRadar + '</div>';
  html += '</div></div>';

  html += '<div class="card"><div class="card-header"><div class="card-title">Dimension Performance Rank</div></div>';
  html += '<div class="card-body">';
  var ranked = DIMENSIONS.map(function(d){
    return {name: DIMENSION_NAMES[d], score: classDims[d]};
  }).sort(function(a,b){return b.score - a.score;});
  
  ranked.forEach(function(item, idx) {
    var pct = Math.round(item.score / 10 * 100);
    html += '<div style="margin-bottom:14px;">';
    html += '<div class="flex-between mb-4"><span class="text-sm font-600">#' + (idx+1) + ' ' + item.name + '</span>';
    html += '<span class="text-sm text-secondary">' + item.score.toFixed(1) + '/10</span></div>';
    html += '<div style="height:8px; background:#e8ecf1; border-radius:4px; overflow:hidden;">';
    html += '<div style="height:100%; width:' + pct + '%; background:linear-gradient(90deg, var(--accent), var(--success)); border-radius:4px;"></div>';
    html += '</div></div>';
  });
  html += '</div></div>';
  html += '</div>';

  area.innerHTML = html;
}

// =========================================
// QUESTION BANK
// =========================================
function renderQuestionBank(area) {
  var allQuestions = CH1_QUESTIONS.concat(CH2_QUESTIONS).concat(CH3_QUESTIONS).concat(CH4_QUESTIONS);
  
  var html = '';
  html += '<h1 class="page-title">Question Bank</h1>';
  html += '<p class="page-subtitle">All questions across both chapters</p>';

  html += '<div class="grid-4 mb-16">';
  html += '<div class="stat-card"><div class="stat-label">Total Questions</div><div class="stat-value">' + allQuestions.length + '</div></div>';
  html += '<div class="stat-card"><div class="stat-label">Chapter 1</div><div class="stat-value">' + CH1_QUESTIONS.length + '</div></div>';
  html += '<div class="stat-card"><div class="stat-label">Chapter 2</div><div class="stat-value">' + CH2_QUESTIONS.length + '</div></div>';
  html += '<div class="stat-card"><div class="stat-label">Chapter 3</div><div class="stat-value">' + CH3_QUESTIONS.length + '</div></div>';
  html += '<div class="stat-card"><div class="stat-label">Chapter 4</div><div class="stat-value">' + CH4_QUESTIONS.length + '</div></div>';
  var basic = allQuestions.filter(function(q){return q.difficulty==='basic';}).length;
  var inter = allQuestions.filter(function(q){return q.difficulty==='intermediate';}).length;
  var adv = allQuestions.filter(function(q){return q.difficulty==='advanced';}).length;
  html += '<div class="stat-card"><div class="stat-label">Difficulty Mix</div><div class="stat-value" style="font-size:14px;">B:'+basic+' / I:'+inter+' / A:'+adv+'</div></div>';
  html += '</div>';

  html += '<div class="card"><div class="card-header">';
  html += '<div class="card-title">Question List</div>';
  html += '<div style="display:flex;gap:8px;">';
  html += '<select class="search-box" onchange="filterQBChapter(this.value)" style="width:auto;">';
  html += '<option value="all">All Chapters</option><option value="ch1">Chapter 1</option><option value="ch2">Chapter 2</option><option value="ch3">Chapter 3</option><option value="ch4">Chapter 4</option><option value="ch5">Chapter 5</option><option value="ch6">Chapter 6</option><option value="ch7">Chapter 7</option><option value="ch8">Chapter 8</option><option value="ch9">Chapter 9</option><option value="ch10">Chapter 10</option>';
  html += '</select>';
  html += '<select class="search-box" onchange="filterQBDiff(this.value)" style="width:auto;">';
  html += '<option value="all">All Difficulties</option><option value="basic">Basic</option><option value="intermediate">Intermediate</option><option value="advanced">Advanced</option>';
  html += '</select></div></div>';
  html += '<div style="overflow-x:auto;">';
  html += '<table class="data-table" id="qbTable"><thead><tr>';
  html += '<th>ID</th><th>Chapter</th><th>Difficulty</th><th>Knowledge Point</th><th>Dimension</th><th>Question</th>';
  html += '</tr></thead><tbody id="qbTableBody">';

  allQuestions.forEach(function(q) {
    var ch = q.id.indexOf('ch1') === 0 ? 'Ch 1' : 'Ch 2';
    var diffClass = q.difficulty === 'basic' ? 'badge-success' : q.difficulty === 'intermediate' ? 'badge-warning' : 'badge-danger';
    html += '<tr data-ch="' + (q.id.indexOf('ch1')===0?'ch1':'ch2') + '" data-diff="' + q.difficulty + '">';
    html += '<td class="text-sm text-muted">' + q.id + '</td>';
    html += '<td>' + ch + '</td>';
    html += '<td><span class="badge ' + diffClass + '">' + q.difficulty + '</span></td>';
    html += '<td class="text-sm">' + q.knowledgePoint + '</td>';
    html += '<td class="text-sm">' + DIMENSION_NAMES[q.dimension] + '</td>';
    html += '<td class="text-sm" style="max-width:300px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + q.question + '</td>';
    html += '</tr>';
  });

  html += '</tbody></table></div></div>';

  area.innerHTML = html;
}

function filterQBChapter(val) {
  var rows = document.querySelectorAll('#qbTableBody tr');
  var diffFilter = document.querySelector('#qbTable')?.closest('.card')?.querySelector('select:nth-child(2)')?.value || 'all';
  rows.forEach(function(row) {
    var chMatch = val === 'all' || row.dataset.ch === val;
    var diffMatch = diffFilter === 'all' || row.dataset.diff === diffFilter;
    row.style.display = chMatch && diffMatch ? '' : 'none';
  });
}

function filterQBDiff(val) {
  var rows = document.querySelectorAll('#qbTableBody tr');
  var chFilter = 'all';
  var sel = document.querySelector('#qbTable')?.closest('.card')?.querySelector('select:first-child');
  if (sel) chFilter = sel.value;
  rows.forEach(function(row) {
    var chMatch = chFilter === 'all' || row.dataset.ch === chFilter;
    var diffMatch = val === 'all' || row.dataset.diff === val;
    row.style.display = chMatch && diffMatch ? '' : 'none';
  });
}

