  html += '<option value="ch1"' + (chKey === 'ch1' ? ' selected' : '') + '>Chapter 1 Project</option>';
  html += '<option value="ch2"' + (chKey === 'ch2' ? ' selected' : '') + '>Chapter 2 Project</option>';
  html += '<option value="ch3"' + (chKey === 'ch3' ? ' selected' : '') + '>Chapter 3 Project</option>';
  html += '<option value="ch4"' + (chKey === 'ch4' ? ' selected' : '') + '>Chapter 4 Project</option>';
  html += '<option value="ch5"' + (chKey === 'ch5' ? ' selected' : '') + '>Chapter 5 Project</option>';
  html += '<option value="ch6"' + (chKey === 'ch6' ? ' selected' : '') + '>Chapter 6 Project</option>';
  html += '<option value="ch7"' + (chKey === 'ch7' ? ' selected' : '') + '>Chapter 7 Project</option>';
  html += '<option value="ch8"' + (chKey === 'ch8' ? ' selected' : '') + '>Chapter 8 Project</option>';
  html += '<option value="ch9"' + (chKey === 'ch9' ? ' selected' : '') + '>Chapter 9 Project</option>';
  html += '<option value="ch10"' + (chKey === 'ch10' ? ' selected' : '') + '>Chapter 10 Project</option>';
  html += '</select>';
