  html += '<div class="card"><div class="card-body"><div style="font-size:24px;font-weight:700;color:var(--accent);">' + totalReplies + '</div><div style="font-size:12px;color:var(--text-secondary);margin-top:4px;">Total Replies</div></div></div>';
  html += '<div class="card"><div class="card-body"><div style="font-size:24px;font-weight:700;color:var(--success);">' + activeCount + '</div><div style="font-size:12px;color:var(--text-secondary);margin-top:4px;">Active Students</div></div></div>';
  html += '<div class="card"><div class="card-body"><div style="font-size:24px;font-weight:700;color:#f39c12;">' + todayNew + '</div><div style="font-size:12px;color:var(--text-secondary);margin-top:4px;">New Today</div></div></div>';
  html += '</div>';
  
