// =========================================
function initTeacherAITutor() {
  var saved = localStorage.getItem("ctp_teacher_ai_conv");
  if (saved) {
    try { TEACHER_AI_STATE.conversation = JSON.parse(saved); } catch(e) {}
  }
  
  if (TEACHER_AI_STATE.conversation.length === 0) {
    TEACHER_AI_STATE.conversation.push({
      role: "ai",
      text: TEACHER_AI_DATA.intro.greeting,
      type: "question"
    });
  }
  
  renderTeacherAIMessages();
  renderTeacherQuickSuggestions();
}

function saveTeacherAIConversation() {
  localStorage.setItem("ctp_teacher_ai_conv", JSON.stringify(TEACHER_AI_STATE.conversation));
}

function toggleTeacherAITutor() {
  var panel = document.getElementById("teacherAiTutorPanel");
  if (!panel) return;
  var isOpen = panel.style.display === "flex";
  panel.style.display = isOpen ? "none" : "flex";
  TEACHER_AI_STATE.isOpen = !isOpen;
  
  if (!isOpen) {
    document.getElementById("teacherAiInput").focus();
  }
}

function openTeacherAITutor(presetMessage) {
  var panel = document.getElementById("teacherAiTutorPanel");
  if (!panel) return;
  panel.style.display = "flex";
  TEACHER_AI_STATE.isOpen = true;
  
  if (presetMessage) {
    document.getElementById("teacherAiInput").value = presetMessage;
    setTimeout(function() { sendTeacherAIMessage(); }, 300);
  } else {
    document.getElementById("teacherAiInput").focus();
  }
}

function renderTeacherAIMessages() {
  var container = document.getElementById("teacherAiMessages");
  if (!container) return;
  var html = "";
  
  TEACHER_AI_STATE.conversation.forEach(function(msg) {
    if (msg.role === "ai") {
      html += '<div style="background:#fff; padding:10px 12px; border-radius:12px 12px 12px 4px; font-size:13px; line-height:1.5; color:#1a2332; box-shadow:0 1px 2px rgba(0,0,0,0.06); max-width:85%; align-self:flex-start;">' + msg.text + '</div>';
      if (msg.hint) {
        html += '<div style="background:#fff9e6; padding:8px 10px; border-radius:8px; font-size:12px; color:#7a5c00; max-width:80%; align-self:flex-start; line-height:1.4;">&#128161; <strong>Hint:</strong> ' + msg.hint + '</div>';
      }
    } else {
      html += '<div style="background:#3498db; padding:10px 12px; border-radius:12px 12px 4px 12px; font-size:13px; line-height:1.5; color:#fff; max-width:85%; align-self:flex-end;">' + msg.text + '</div>';
    }
  });
  
  container.innerHTML = html;
  container.scrollTop = container.scrollHeight;
}

function renderTeacherQuickSuggestions() {
  var container = document.getElementById("teacherQuickSuggestions");
  if (!container) return;
  
  var suggestions = [
    "Course planning",
    "Question design",
    "Student performance",
    "Engagement tips"
  ];
  
  var html = "";
  suggestions.forEach(function(s) {
    html += '<span style="padding:4px 10px; background:#e8f4fd; color:#3498db; border-radius:14px; font-size:11px; cursor:pointer; white-space:nowrap;" onclick="sendTeacherQuickSuggestion(\'' + s + '\')">' + s + '</span>';
  });
  container.innerHTML = html;
}

function sendTeacherQuickSuggestion(text) {
  document.getElementById("teacherAiInput").value = text;
  sendTeacherAIMessage();
}

function sendTeacherAIMessage() {
  var input = document.getElementById("teacherAiInput");
  var text = input.value.trim();
  if (!text) return;
  
  TEACHER_AI_STATE.conversation.push({ role: "user", text: text });
  input.value = "";
  renderTeacherAIMessages();
  
  var container = document.getElementById("teacherAiMessages");
  var thinkingDiv = document.createElement("div");
  thinkingDiv.id = "teacherAiThinking";
  thinkingDiv.style.cssText = "background:#f0f2f5; padding:8px 12px; border-radius:12px; font-size:13px; color:#8a9bae; align-self:flex-start;";
  thinkingDiv.innerHTML = "Thinking...";
  container.appendChild(thinkingDiv);
  container.scrollTop = container.scrollHeight;
  
  setTimeout(function() {
    var response = generateTeacherAIResponse(text);
    var thinking = document.getElementById("teacherAiThinking");
    if (thinking) thinking.remove();
    
    TEACHER_AI_STATE.conversation.push(response);
    saveTeacherAIConversation();
    renderTeacherAIMessages();
  }, 900 + Math.random() * 700);
}

function generateTeacherAIResponse(userInput) {
  var input = userInput.toLowerCase();
  
  var bestMatch = null;
  var bestMatchCount = 0;
  var bestMatchIndex = -1;
  
  TEACHER_AI_DATA.scenarios.forEach(function(scenario, idx) {
    var matchCount = 0;
    scenario.keywords.forEach(function(kw) {
      if (input.indexOf(kw.toLowerCase()) !== -1) matchCount++;
    });
    if (matchCount > bestMatchCount && matchCount > 0) {
      bestMatchCount = matchCount;
      bestMatch = scenario;
      bestMatchIndex = idx;
    }
  });
  
  // Continue same scenario or start new one
  if (TEACHER_AI_STATE.currentScenario !== null && 
      bestMatchIndex === TEACHER_AI_STATE.currentScenario &&
      TEACHER_AI_STATE.responseIndex < TEACHER_AI_STATE.scenarioResponses.length - 1) {
    TEACHER_AI_STATE.responseIndex++;
  } else if (bestMatch) {
    TEACHER_AI_STATE.currentScenario = bestMatchIndex;
    TEACHER_AI_STATE.scenarioResponses = bestMatch.responses;
    TEACHER_AI_STATE.responseIndex = 0;
  } else {
    TEACHER_AI_STATE.currentScenario = null;
    TEACHER_AI_STATE.responseIndex = 0;
    var fallback = TEACHER_AI_DATA.fallback_responses[Math.floor(Math.random() * TEACHER_AI_DATA.fallback_responses.length)];
    return { role: "ai", text: fallback, type: "question" };
  }
  
  if (TEACHER_AI_STATE.currentScenario !== null) {
    var scenario = TEACHER_AI_DATA.scenarios[TEACHER_AI_STATE.currentScenario];
    var respIdx = Math.min(TEACHER_AI_STATE.responseIndex, scenario.responses.length - 1);
    var resp = scenario.responses[respIdx];
    
    var encouragement = Math.random() > 0.4 && resp.type !== "answer"
      ? TEACHER_AI_DATA.encouragement_phrases[Math.floor(Math.random() * TEACHER_AI_DATA.encouragement_phrases.length)] + " "
      : "";
    
    return {
      role: "ai",
      text: encouragement + resp.text,
      hint: resp.hint || "",
      type: resp.type
    };
  }
  
  return { role: "ai", text: "That's a great teaching question. What aspects of this topic interest you most?", type: "question" };
}



