// STUDENT DATA IMPORT (Admin End)
// ============================================================

function parseStudentImportFile(file) {
  return new Promise(function(resolve, reject) {
    var reader = new FileReader();
    reader.onload = function(e) {
      try {
        var data = JSON.parse(e.target.result);
        resolve({ file: file.name, data: data, error: null });
      } catch(err) {
        resolve({ file: file.name, data: null, error: err.message });
      }
    };
    reader.onerror = function() {
      resolve({ file: file.name, data: null, error: 'File read error' });
    };
    reader.readAsText(file);
  });
}

function findOrCreateStudentFromImport(importData) {
  var info = importData.studentInfo || {};
  var importId = info.studentId || '';
  var importName = info.name || '';
  var importEmail = info.email || '';
  var importClass = info.classCode || '';

  var students = v7AdminGetStudents();
  var matchedId = null;
  var matchType = 'new';

  // Try matching by studentId first
  if (importId) {
    for (var sid in students) {
      if (students.hasOwnProperty(sid)) {
        if (sid === importId || students[sid].studentId === importId) {
          matchedId = sid;
          matchType = 'id';
          break;
        }
      }
    }
  }

  // Try matching by name + class
  if (!matchedId && importName) {
    for (var sid2 in students) {
      if (students.hasOwnProperty(sid2)) {
        var s = students[sid2];
        if (s.name === importName) {
          if (!importClass || s.classId === importClass || s.classCode === importClass) {
            matchedId = sid2;
            matchType = 'name';
            break;
          }
        }
      }
    }
  }

  // Try matching by email
  if (!matchedId && importEmail) {
    for (var sid3 in students) {
      if (students.hasOwnProperty(sid3)) {
        var s3 = students[sid3];
        if (s3.email === importEmail) {
          matchedId = sid3;
          matchType = 'email';
          break;
        }
      }
    }
  }

  return {
    matchedId: matchedId,
    matchType: matchType,
    importId: importId,
    importName: importName,
    importEmail: importEmail,
    importClass: importClass
  };
}

function applyImportDataToStudent(studentId, importData, isNew) {
  var students = v7AdminGetStudents();
  var info = importData.studentInfo || {};

  if (isNew) {
    var newId = info.studentId || ('stu_' + Date.now() + '_' + Math.floor(Math.random() * 1000));
    students[newId] = {
      studentId: newId,
      name: info.name || 'Unknown',
      email: info.email || '',
      classId: info.classCode || 'Unassigned',
      password: '123456',
      createdAt: new Date().toISOString()
    };
    studentId = newId;
  }

  // Load existing student data
  var existingData = v7LoadStudentData(studentId) || {};

  // Merge import data
  if (importData.chaptersCompleted) existingData.chaptersCompleted = importData.chaptersCompleted;
  if (importData.chapterScores) existingData.chapterScores = importData.chapterScores;
  if (importData.pblProjects) existingData.pblProjects = importData.pblProjects;
  if (importData.questionHistory) existingData.questionHistory = importData.questionHistory;
  if (importData.dimensionScores) existingData.dimensionScores = importData.dimensionScores;
  if (importData.dimensionAttempts) existingData.dimensionAttempts = importData.dimensionAttempts;
  if (importData.practiceSessions != null) existingData.practiceSessions = importData.practiceSessions;
  if (importData.streak != null) existingData.streak = importData.streak;
  if (importData.recommendations) existingData.recommendations = importData.recommendations;
  if (importData.currentDifficulty) existingData.currentDifficulty = importData.currentDifficulty;
  if (importData.lastActivity) existingData.lastActivity = importData.lastActivity;

  // Pretest / Posttest
  if (importData.pretest) {
    existingData.pretestScore = importData.pretest.score != null ? importData.pretest.score : existingData.pretestScore;
    existingData.pretestTaken = importData.pretest.taken != null ? importData.pretest.taken : existingData.pretestTaken;
    if (importData.pretest.date) existingData.pretestDate = importData.pretest.date;
  }
  if (importData.posttest) {
    existingData.posttestScore = importData.posttest.score != null ? importData.posttest.score : existingData.posttestScore;
    existingData.posttestTaken = importData.posttest.taken != null ? importData.posttest.taken : existingData.posttestTaken;
    if (importData.posttest.date) existingData.posttestDate = importData.posttest.date;
  }

  // Milestones
  if (importData.milestones) existingData.milestones = importData.milestones;

  // Ensure id
  existingData.id = studentId;
  if (!existingData.name) existingData.name = info.name || 'Unknown';
  if (!existingData.classCode) existingData.classCode = info.classCode || '';

  // Save student data
  v7SaveStudentData(studentId, existingData);

  // Save student record
  if (students[studentId]) {
    students[studentId].name = info.name || students[studentId].name;
    students[studentId].email = info.email || students[studentId].email;
    if (info.classCode) students[studentId].classId = info.classCode;
    // Update question count
    students[studentId].questionCount = (existingData.questionHistory || []).length;
    students[studentId].lastActivity = existingData.lastActivity || students[studentId].lastActivity;
  }

  v7SaveStudents(students);

  // Save AI conversations if any
  if (importData.aiConversations) {
    try {
      var aiKey = v7GetStudentDataKey(studentId) + '_ai_conv';
      localStorage.setItem(aiKey, JSON.stringify(importData.aiConversations));
    } catch(e) {}
  }

  // Save messages if any
  if (importData.discussionPosts) {
    // Forum posts are global; skip per-student save
  }

  // Recalculate derived fields
  var chCompleted = 0;
  var chTotal = 0;
  if (existingData.chaptersCompleted) {
    for (var ck in existingData.chaptersCompleted) {
      if (existingData.chaptersCompleted.hasOwnProperty(ck)) {
        chTotal++;
        if (existingData.chaptersCompleted[ck]) chCompleted++;
      }
    }
  }
  students[studentId].chaptersCompleted = chCompleted;
  students[studentId].chapterTotal = chTotal;

  v7SaveStudents(students);

  return {
    studentId: studentId,
    name: info.name || 'Unknown',
    chaptersCompleted: chCompleted,
    questions: (existingData.questionHistory || []).length,
    pblProjects: importData.pblProjects ? Object.keys(importData.pblProjects).length : 0,
    aiConversations: importData.aiConversations ? importData.aiConversations.length : 0
  };
}

function importStudentFiles(files) {
  var promises = [];
  for (var i = 0; i < files.length; i++) {
    promises.push(parseStudentImportFile(files[i]));
  }

  Promise.all(promises).then(function(results) {
    var summary = {
      success: [],
      failed: [],
      created: [],
      updated: [],
      skipped: []
    };

    for (var j = 0; j < results.length; j++) {
      var result = results[j];
      if (result.error) {
        summary.failed.push({ file: result.file, reason: result.error });
        continue;
      }

      var importData = result.data;
      if (!importData || !importData.studentInfo) {
        summary.failed.push({ file: result.file, reason: 'Invalid format: missing studentInfo' });
        continue;
      }

      try {
        var match = findOrCreateStudentFromImport(importData);
        var isNew = match.matchType === 'new';

        var entry = {
          file: result.file,
          name: (importData.studentInfo && importData.studentInfo.name) || 'Unknown',
          studentId: (importData.studentInfo && importData.studentInfo.studentId) || '',
          matchType: match.matchType,
          chaptersCompleted: 0,
          questions: 0,
          pblProjects: 0,
          aiConversations: 0
        };

        if (isNew) {
          var applied = applyImportDataToStudent(match.matchedId, importData, isNew);
          entry.name = applied.name;
          entry.studentId = applied.studentId;
          entry.chaptersCompleted = applied.chaptersCompleted;
          entry.questions = applied.questions;
          entry.pblProjects = applied.pblProjects;
          entry.aiConversations = applied.aiConversations;
          summary.success.push(entry);
          summary.created.push(entry);
        } else {
          // Student already exists - skip
          var existingData = v7LoadStudentData(match.matchedId);
          if (existingData) {
            var cc = 0;
            if (existingData.chaptersCompleted) {
              for (var ck in existingData.chaptersCompleted) {
                if (existingData.chaptersCompleted.hasOwnProperty(ck) && existingData.chaptersCompleted[ck]) cc++;
              }
            }
            entry.name = existingData.name || entry.name;
            entry.studentId = existingData.studentId || entry.studentId;
            entry.chaptersCompleted = cc;
            entry.questions = (existingData.questionHistory || []).length;
            entry.pblProjects = (existingData.pblProjects || []).length;
            entry.aiConversations = (existingData.aiConversations || []).length;
          }
          summary.skipped.push(entry);
        }
      } catch(err) {
        summary.failed.push({ file: result.file, reason: err.message });
      }
    }

    // Refresh student list and dashboard
    v7RefreshStudentStats();
    if (AppState.currentPage === 'dashboard') {
      renderAdminDashboardV7(document.getElementById('contentArea'));
    } else {
      renderStudentListV7(document.getElementById('contentArea'));
    }

    // Show import result
    showImportResultModal(summary);
  });
}

function v7RefreshStudentStats() {
  var students = v7AdminGetStudents();
  for (var sid in students) {
    if (students.hasOwnProperty(sid)) {
      var data = v7LoadStudentData(sid);
      if (data) {
        students[sid].questionCount = (data.questionHistory || []).length;
        students[sid].lastActivity = data.lastActivity || students[sid].lastActivity;
        if (data.chaptersCompleted) {
          var cc = 0;
          var ct = 0;
          for (var ck in data.chaptersCompleted) {
            if (data.chaptersCompleted.hasOwnProperty(ck)) {
              ct++;
              if (data.chaptersCompleted[ck]) cc++;
            }
          }
          students[sid].chaptersCompleted = cc;
          students[sid].chapterTotal = ct;
        }
      }
    }
  }
  v7SaveStudents(students);
}

